/// Builds the initial Detailed/Named plan for the no-manifest
/// semantic subset (DEMO-4): scanned pieces lower with scan
/// authorization, manifest pieces keep their own authority. Used
/// only by the scan subset mint; broad/capture plans grant the same
/// standard-layout legs (interface linkage, sole-complete table,
/// typed-getter export) while the live-return leg stays subset-only.
pub(crate) fn build_from_sources_scan_authorized(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    pinned: &PinnedObjects,
) -> AttachPlan {
    let (mut pinned_id, mut compatible) = pinned_manifest_lookups(pinned);
    let mut discovered: Vec<Discovered<'_>> = scanned
        .iter()
        .map(|module| lower_scanned_with(module, true))
        .collect();
    let mut orphaned = Vec::new();
    for manifest in manifests {
        let (module, skipped) = lower_manifest(manifest, &mut pinned_id, &mut compatible);
        discovered.extend(module);
        orphaned.extend(skipped);
    }
    let mut plan = merge(
        discovered,
        manifests.iter().map(|m| m.vendor_interfaces.len()).sum(),
        manifests.first().map_or_else(
            || "absent".to_string(),
            |m| acquisition_label(&m.interface_list),
        ),
        &BTreeMap::new(),
        ExistingAllocation {
            slots: 0,
            active: &BTreeMap::new(),
            revivable: &BTreeMap::new(),
            retired_keys: &BTreeMap::new(),
            retired_slots: &BTreeSet::new(),
            prior_slots: &[],
            prior_identities: &BTreeMap::new(),
            owned: &BTreeMap::new(),
            first_plan: None,
            first_plan_had_provider: false,
        },
        false,
        AdmissionPolicy::detailed(),
        AdmissionScope::Named,
        false,
    );
    plan.skipped.extend(orphaned);
    plan.note_object_identities(pinned);
    plan
}

/// Complete target requirements before table/slot admission. These are negative
/// completeness and ambiguity facts, never permission to read arguments.
pub(crate) struct SemanticSourceClaims {
    pub(crate) providers: BTreeMap<PinnedObjectId, BTreeSet<AttachKey>>,
    pub(crate) degraded: BTreeSet<AttachKey>,
    pub(crate) incomplete: BTreeSet<PinnedObjectId>,
}

pub(crate) fn semantic_source_claims(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    pinned: &PinnedObjects,
) -> SemanticSourceClaims {
    semantic_source_claims_with(scanned, manifests, pinned, false)
}

/// [`semantic_source_claims`] for the no-manifest scan subset:
/// scanned pieces lower with scan authorization, so a key is
/// degraded only for the same rival/ambiguity reasons as a
/// manifest key — never merely for being scan-discovered.
pub(crate) fn semantic_source_claims_scan_authorized(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    pinned: &PinnedObjects,
) -> SemanticSourceClaims {
    semantic_source_claims_with(scanned, manifests, pinned, true)
}

fn semantic_source_claims_with(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    pinned: &PinnedObjects,
    scan_authorized: bool,
) -> SemanticSourceClaims {
    let affecting = |name: &str| {
        crate::kinds::descriptor(name)
            .is_none_or(|descriptor| descriptor != SlotSemantics::COUNT_ONLY)
    };
    let mut incomplete: BTreeSet<_> = scanned
        .iter()
        .filter(|module| {
            // The same witness `lower_scanned` publishes by, so semantic
            // completeness and the reported walk never disagree about one
            // table.
            let exports = ObjectExports {
                object: module.scanned.key,
                symbols: &module.exports,
                getter_present: module.getter_present,
                witness_fault: module.witness_fault,
            };
            module
                .scanned
                .tables
                .iter()
                .enumerate()
                .any(|(index, table)| {
                    let walk = published_walk(
                        index,
                        &module.scanned.tables,
                        &module.scanned.interfaces,
                        &exports,
                    );
                    walk != "full" || table.unpinned.iter().any(|entry| affecting(&entry.subject))
                })
        })
        .map(|module| module.object)
        .collect();
    let mut pieces: Vec<_> = scanned
        .iter()
        .map(|module| lower_scanned_with(module, scan_authorized))
        .collect();
    let mut selection_claims = Vec::new();
    for manifest in manifests {
        let (piece, _) = lower_manifest(
            manifest,
            |key, path| pinned.id_for_manifest(key, path),
            // A retained target rejected by ordinary ABI admission still
            // belongs to the complete demand; omitting it cannot certify a prefix.
            |_, _| true,
        );
        if let Some(piece) = &piece {
            if manifest.surfaces.iter().any(|surface| {
                (matches!(surface.acquisition, Acquisition::Ok)
                    && !crate::manifest_input::surface_function_inventory_complete(surface))
                    || surface.functions.iter().any(|function| {
                        affecting(&function.name)
                            && !matches!(
                                function.resolution,
                                Resolution::Resolved { .. } | Resolution::NullPointer
                            )
                    })
            }) {
                // Only typed null/absent entries prove optional absence.
                // A successfully acquired undecoded table is incomplete;
                // diagnostic strings cannot stand in for either fact.
                incomplete.insert(piece.object);
            }
            if manifest.selection_evidence.tables.iter().any(|table| {
                crate::manifest_input::selection_table_inventory_incomplete(
                    &manifest.selection_evidence,
                    table,
                )
            }) {
                incomplete.insert(piece.object);
            }
            for (table_id, targets) in
                crate::discovery::engine::manifest_selection_targets(manifest, pinned)
            {
                if manifest
                    .selection_evidence
                    .tables
                    .iter()
                    .find(|table| table.id == table_id)
                    .is_some_and(|table| {
                        table
                            .functions
                            .iter()
                            .filter(|function| {
                                matches!(function.resolution, Resolution::Resolved { .. })
                            })
                            .count()
                            != targets.len()
                    })
                {
                    incomplete.insert(piece.object);
                }
                selection_claims.extend(targets.into_iter().map(|target| (piece.object, target)));
            }
        }
        pieces.extend(piece);
    }
    let mut providers = BTreeMap::<_, BTreeSet<_>>::new();
    let mut owners = BTreeMap::<_, BTreeSet<_>>::new();
    let mut names = BTreeMap::<_, BTreeMap<String, bool>>::new();
    for piece in pieces {
        for target in piece.targets {
            let key = AttachKey {
                object: target.object,
                file_offset: target.file_offset,
            };
            providers.entry(piece.object).or_default().insert(key);
            owners.entry(key).or_default().insert(piece.object);
            let claims = names.entry(key).or_default();
            for name in std::iter::once(presented_name(target.name_authorized, target.name))
                .chain(target.aliases)
            {
                claims
                    .entry(name.to_owned())
                    .and_modify(|attested| *attested |= target.semantic_authorized)
                    .or_insert(target.semantic_authorized);
            }
        }
    }
    let mut selection_keys = BTreeSet::new();
    for (provider, target) in selection_claims {
        let key = AttachKey {
            object: target.object,
            file_offset: target.file_offset,
        };
        providers.entry(provider).or_default().insert(key);
        owners.entry(key).or_default().insert(provider);
        names
            .entry(key)
            .or_default()
            .entry(target.name.to_owned())
            .or_insert(false);
        // Selection-only input grants no semantic authority, even when a
        // target also has a trusted name. Keep that negative claim before
        // provider selection/admission can hide it.
        selection_keys.insert(key);
    }
    let degraded = names
        .into_iter()
        .filter_map(|(key, mut names)| {
            if names.len() > 1 {
                names.remove(UNKNOWN_FUNCTION_NAME);
            }
            let labels = names.keys().cloned().collect::<Vec<_>>();
            (selection_keys.contains(&key)
                || owners[&key].len() > 1
                || names.values().any(|attested| !attested)
                || crate::kinds::descriptor_index(&labels).1)
                .then_some(key)
        })
        .collect();
    SemanticSourceClaims {
        providers,
        degraded,
        incomplete,
    }
}

#[allow(clippy::too_many_arguments)]
fn build_from_sources_with_policy(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    prearm: &[PrearmPlanPiece],
    pinned: &PinnedObjects,
    broad_admit: bool,
    admission_policy: AdmissionPolicy,
    admission_scope: AdmissionScope,
    counter_hint: bool,
) -> AttachPlan {
    let (pinned_id, compatible) = pinned_manifest_lookups(pinned);
    let mut plan = build_from_sources_with(
        scanned,
        manifests,
        prearm,
        pinned_id,
        compatible,
        Some(pinned),
        None,
        ExistingAllocation {
            slots: 0,
            active: &BTreeMap::new(),
            revivable: &BTreeMap::new(),
            retired_keys: &BTreeMap::new(),
            retired_slots: &BTreeSet::new(),
            prior_slots: &[],
            prior_identities: &BTreeMap::new(),
            owned: &BTreeMap::new(),
            first_plan: None,
            first_plan_had_provider: false,
        },
        broad_admit,
        admission_policy,
        admission_scope,
        counter_hint,
    );
    plan.note_object_identities(pinned);
    plan
}

/// Historical allocations, their still-active subset, and its current owners
/// travel together. Retired slots count against capacity even though they are
/// absent from `active`.
struct ExistingAllocation<'a> {
    slots: usize,
    active: &'a BTreeMap<AttachKey, usize>,
    /// Absence-retired targets cleared for same-target revival this
    /// rebuild (see [`AttachPlan::revivable`): they reoccupy their old
    /// positions at extend, so merge charges them no new slot. Cross-ID
    /// same-file reclaim (slot reclaim) also reads this: a new pin for the
    /// same file reuses a revivable retired index with the same file
    /// offset and path, so short-lived churn stops burning fresh slots.
    revivable: &'a BTreeMap<AttachKey, RetiredPositions>,
    /// Exact target -> retired generations, for the same reclaim memory.
    retired_keys: &'a BTreeMap<AttachKey, RetiredPositions>,
    /// Retired positions, for the same reclaim memory.
    retired_slots: &'a BTreeSet<usize>,
    /// Allocated slots by index, for cross-ID reclaim path comparison
    /// (old retired index path vs new target path). Empty for an initial
    /// build; borrowed from the prior plan for a rebuild.
    prior_slots: &'a [Slot],
    /// Recorded identities of the prior plan's objects: cross-ID reclaim
    /// requires a positive match against the returning object.
    prior_identities: &'a BTreeMap<PinnedObjectId, TargetObject>,
    /// `active`, under the object of each module that currently owns a
    /// target: a module listed here is already admitted (G-03).
    owned: &'a BTreeMap<PinnedObjectId, BTreeSet<AttachKey>>,
    /// Objects in the capture's first plan input (`None` for an initial
    /// build, whose input IS the first plan). A closure array gets its
    /// heuristic prefix only when its object is here (PA-5 C1).
    first_plan: Option<&'a BTreeSet<PinnedObjectId>>,
    /// Whether the capture's first plan admitted a non-closure provider
    /// onto a slot (PA-9/C1). Read only when `first_plan` is `Some`; an
    /// initial build sets it as its providers are admitted instead.
    first_plan_had_provider: bool,
}

/// The standard manifest lookups over live pins: manifest keys resolve to
/// pinned objects, and a retained target is admitted only under the
/// provider's own ABI. Shared by the build paths and the conservative plan
/// cursor so manifest keys cannot resolve differently between them.
fn pinned_manifest_lookups(
    pinned: &PinnedObjects,
) -> (
    impl FnMut(ObjectKey, &str) -> Option<PinnedObjectId> + '_,
    impl FnMut(PinnedObjectId, PinnedObjectId) -> bool + '_,
) {
    (
        |key, path| pinned.id_for_manifest(key, path),
        |provider, target| {
            matches!(
                (pinned.abi_for(provider), pinned.abi_for(target)),
                (Some(provider), Some(target)) if provider == target
            )
        },
    )
}

#[allow(clippy::too_many_arguments)]
fn build_from_sources_with(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    prearm: &[PrearmPlanPiece],
    mut pinned_id: impl FnMut(ObjectKey, &str) -> Option<PinnedObjectId>,
    mut compatible: impl FnMut(PinnedObjectId, PinnedObjectId) -> bool,
    pinned: Option<&PinnedObjects>,
    new_identities: Option<&BTreeMap<PinnedObjectId, TargetObject>>,
    allocated: ExistingAllocation<'_>,
    broad_admit: bool,
    admission_policy: AdmissionPolicy,
    admission_scope: AdmissionScope,
    counter_hint: bool,
) -> AttachPlan {
    let mut discovered: Vec<Discovered<'_>> = scanned.iter().map(lower_scanned).collect();
    let mut orphaned = Vec::new();
    for manifest in manifests {
        let (module, skipped) = lower_manifest(manifest, &mut pinned_id, &mut compatible);
        discovered.extend(module);
        orphaned.extend(skipped);
    }
    // Pre-arm pieces arrive resolved against the current pin set (the
    // engine resolves fresh before each build, so a retired object simply
    // has no piece here).
    discovered.extend(prearm.iter().map(lower_prearm));
    // Identities of the objects this rebuild names, from the pins in hand
    // (or an explicit test injection). Merge needs them for the fail-closed
    // cross-ID reclaim predicate; the plan records them after the build.
    let new_identities: BTreeMap<PinnedObjectId, TargetObject> =
        if let Some(identities) = new_identities {
            identities.clone()
        } else {
            let mut identities = BTreeMap::new();
            if let Some(pinned) = pinned {
                for module in &discovered {
                    for object in std::iter::once(module.object)
                        .chain(module.targets.iter().map(|target| target.object))
                    {
                        if identities.contains_key(&object) {
                            continue;
                        }
                        if let Some(summary) = pinned.summary(object) {
                            identities.insert(object, target_object_from_summary(&summary));
                        }
                    }
                }
            }
            identities
        };
    // The scan never calls the provider, so it contributes no C_GetInterfaceList
    // enumeration and leaves nothing present-but-undecoded: every interface it
    // records names a table it decoded. Only a manifest can report either.
    let mut plan = merge(
        discovered,
        manifests.iter().map(|m| m.vendor_interfaces.len()).sum(),
        manifests.first().map_or_else(
            || "absent".to_string(),
            |m| acquisition_label(&m.interface_list),
        ),
        &new_identities,
        allocated,
        broad_admit,
        admission_policy,
        admission_scope,
        counter_hint,
    );
    plan.skipped.extend(orphaned);
    plan
}

#[cfg(test)]
mod decoded_occurrence_count_tests {
    use super::*;

    fn target(name: &'static str, object: u32, file_offset: u64) -> Target<'static> {
        Target {
            name,
            object: PinnedObjectId(object),
            object_path: "/lib/provider.so",
            file_offset,
            fork_safe: false,
            semantic_authorized: false,
            standard_layout_evidence: None,
            reproven_unfinished: false,
            name_authorized: false,
            unproven: Some(UnprovenNames::HeuristicTable),
            table: None,
            ordinal: None,
            aliases: Vec::new(),
        }
    }

    fn piece(
        source: &'static str,
        targets: Vec<Target<'static>>,
        skipped: Vec<Skipped>,
    ) -> Discovered<'static> {
        Discovered {
            object: PinnedObjectId(1),
            key: ObjectKey {
                device: p11scope_manifest::maps::Device { major: 0, minor: 1 },
                inode: 1,
            },
            path: "/lib/provider.so",
            module_named: false,
            source,
            tables: Vec::new(),
            interfaces: 0,
            surfaces: Vec::new(),
            entries_seen: targets.len() + skipped.len(),
            targets,
            skipped,
            scan_evidence: None,
        }
    }

    fn skip(subject: &str, reason: &str) -> Skipped {
        Skipped {
            subject: subject.into(),
            reason: reason.into(),
        }
    }

    /// The one-piece shortcut equals the occurrence set on repeated
    /// targets and skips; corroborating pieces still dedupe through it.
    #[test]
    fn one_piece_count_equals_the_occurrence_set() {
        let single = [piece(
            "scan",
            vec![
                target("C_Sign", 1, 8),
                target("C_Sign", 1, 8),
                target("C_Sign", 1, 16),
                target("C_Init", 2, 8),
                target("C_Sign", 1, 8),
            ],
            vec![skip("C_Foo", "null pointer"), skip("C_Foo", "null pointer")],
        )];
        assert_eq!(decoded_occurrence_count(&single), 7);
        assert_eq!(decoded_occurrence_count_by_set(&single), 7);
        let empty = [piece("scan", Vec::new(), Vec::new())];
        assert_eq!(decoded_occurrence_count(&empty), 0);
        assert_eq!(decoded_occurrence_count_by_set(&empty), 0);
        let corroborated = [
            piece(
                "scan",
                vec![target("C_Sign", 1, 8), target("C_Sign", 1, 8)],
                Vec::new(),
            ),
            piece("manifest", vec![target("C_Sign", 1, 8)], Vec::new()),
        ];
        assert_eq!(decoded_occurrence_count(&corroborated), 2);
        assert_eq!(
            decoded_occurrence_count(&corroborated),
            decoded_occurrence_count_by_set(&corroborated)
        );
    }
}

#[cfg(test)]
fn build_from_test_sources(scanned: &[ReconciledModule], manifests: &[Manifest]) -> AttachPlan {
    build_from_test_sources_with_policy(scanned, manifests, AdmissionPolicy::detailed())
}

#[cfg(test)]
fn build_from_test_sources_with_policy(
    scanned: &[ReconciledModule],
    manifests: &[Manifest],
    admission_policy: AdmissionPolicy,
) -> AttachPlan {
    build_from_sources_with(
        scanned,
        manifests,
        &[],
        |key, _| u32::try_from(key.inode).ok().map(PinnedObjectId),
        |_, _| true,
        None,
        None,
        ExistingAllocation {
            slots: 0,
            active: &BTreeMap::new(),
            revivable: &BTreeMap::new(),
            retired_keys: &BTreeMap::new(),
            retired_slots: &BTreeSet::new(),
            prior_slots: &[],
            prior_identities: &BTreeMap::new(),
            owned: &BTreeMap::new(),
            first_plan: None,
            first_plan_had_provider: false,
        },
        false,
        admission_policy,
        AdmissionScope::Named,
        false,
    )
}

/// Mislabel guard: an unlinked heuristic table's ordinal label is a positional
/// guess — its slots are named `unknown`, never e.g. `C_Sign`. Only
/// linkage-or-manifest authorization presents PKCS#11 names. Admission is
/// untouched: linkage is preferred, never gated.
fn presented_name(authorized: bool, name: &str) -> &str {
    if authorized {
        name
    } else {
        UNKNOWN_FUNCTION_NAME
    }
}

/// The lowered target rows of one scanned table: each decoded entry with the
/// object it attaches into. Shared by [`lower_scanned`] and the conservative
/// plan cursor, so the cursor's live-key set is enumerated by the same row
/// function merge uses and cannot drift from it.
fn scanned_table_rows(
    module: &ReconciledModule,
    table: usize,
) -> impl Iterator<Item = (&ScannedEntry, PinnedObjectId)> + '_ {
    module.scanned.tables[table]
        .entries
        .iter()
        .zip(module.entry_objects[table].iter().copied())
}

fn lower_scanned(module: &ReconciledModule) -> Discovered<'_> {
    lower_scanned_with(module, false)
}

/// The 2.x key-operation entries a sole-complete-table grant requires
/// non-NULL and in own code: every 2.x function with an object-capture
/// descriptor (the decoder's read set). Pinned by test against
/// `kinds::object_descriptor` over `FUNCTION_LIST_FIELDS`.
const SOLE_COMPLETE_REQUIRED_2X: [&str; 20] = [
    "C_CreateObject",
    "C_CopyObject",
    "C_DestroyObject",
    "C_GetObjectSize",
    "C_GetAttributeValue",
    "C_SetAttributeValue",
    "C_FindObjects",
    "C_EncryptInit",
    "C_DecryptInit",
    "C_DigestKey",
    "C_SignInit",
    "C_SignRecoverInit",
    "C_VerifyInit",
    "C_VerifyRecoverInit",
    "C_GenerateKey",
    "C_GenerateKeyPair",
    "C_WrapKey",
    "C_UnwrapKey",
    "C_DeriveKey",
    "C_SetOperationState",
];

/// Standard-layout shape (controller ruling 2026-11-11 clause 1): the
/// table's version field is 2.x/3.x and its decoded slot count matches
/// that version's standard layout (2.x = 68, 3.0/3.1 = 92, 3.2+ = 104),
/// or it is the proven 68-slot legacy prefix of a 3.x table whose wider
/// layouts were refuted (`extension_impossible`).
fn standard_layout_shape(table: &ScannedTable) -> bool {
    let expected = match table.version {
        (2, _) => 68,
        (3, 0 | 1) => 92,
        (3, _) => 104,
        _ => return false,
    };
    table.decoded_slot_count() == expected
        || (table.version.0 == 3 && table.extension_impossible && table.decoded_slot_count() == 68)
}

/// The ruling's common prerequisites (controller ruling 2026-11-11
/// clause 1) that every standard-layout admission leg must satisfy:
/// the version/count shape holds, every retained entry points
/// into the provider's own object, and no non-NULL slot was moved
/// aside unpinned — clause 1 constrains every non-NULL slot, so an
/// unusable or unreconciled target the retained-entry proof never
/// covered refuses the whole table. The sole-complete and
/// getter-export legs re-prove this core inside their stricter
/// predicates; the interface-linkage and live-return legs prove it
/// here, so no leg can grant argument-read authority on linkage
/// or return evidence alone. A refusal keeps the usable
/// observations count-only; NULL holes stay admissible.
///
/// Amendment 22:45 2026-11-11: one exemption — a
/// `C_GetFunctionList`/`C_GetInterface`/`C_GetInterfaceList` entry
/// resolving outside the provider's own object keeps the proof.
/// Both bind paths refuse a cross-object forward the pinned
/// target's own `.dynsym` does not define at that exact offset
/// (see `forwarded_bootstrap_verified`), so a binder-kept forward
/// was resolved by name: ordinary linker interposition when a
/// provider loads first and globally visible (p11-kit-proxy loads
/// `libp11-kit.so` first). The exempted slots are getter
/// descriptors, so they stay count-only and never read arguments;
/// only proven own-object slots gain authority. Any other foreign
/// entry, or a wrong-offset forward (bind moves it to `unpinned`,
/// which refuses above), still refuses the whole table.
///
/// B5 2026-11-12: the exemption checks the binder's per-entry
/// `forward_verified` proof, not just the getter name. A retained
/// cross-object getter the binder never verified — a module
/// produced on a path that bypassed bind verification — refuses,
/// exactly as before the exemption.
fn standard_layout_core(module: &ReconciledModule, index: usize) -> bool {
    let scanned = &module.scanned;
    let table = &scanned.tables[index];
    if !standard_layout_shape(table) || !table.unpinned.is_empty() {
        return false;
    }
    let Some(objects) = module.entry_objects.get(index) else {
        return false;
    };
    let Some(verified) = module.forward_verified.get(index) else {
        return false;
    };
    objects.len() == table.entries.len()
        && verified.len() == table.entries.len()
        && table
            .entries
            .iter()
            .zip(objects.iter())
            .zip(verified.iter())
            .all(|((entry, object), verified)| {
                (entry.object == scanned.key && *object == module.object)
                    || (entry.object != scanned.key && forwardable_getter(entry.name) && *verified)
            })
}

/// Typed-getter-export leg (controller ruling 2026-11-11 clause 1): the
/// sole-complete leg generalized past 68 slots and past the 2.x getter
/// exclusion. The provider exports `C_GetFunctionList` or
/// `C_GetInterface`, the one scanned table's version matches its
/// standard slot count on a full walk, every retained entry is in the
/// provider's own object and agrees per-ordinal with its exports, and
/// the same ambient guards as the sole leg hold (finished scan, no
/// vendor interface claim, no witness fault, not double-loaded,
/// required key-operation entries present). Multi-static-table
/// providers reach authority through interface linkage, not this leg;
/// live siblings are observations, not rivals.
fn getter_export_authorized(
    module: &ReconciledModule,
    index: usize,
    exports: &ObjectExports<'_>,
    score: &TableEvidenceScore,
    scan_finished: bool,
) -> bool {
    let scanned = &module.scanned;
    // Live tables are runtime observations, never scan rivals: the leg
    // needs exactly one static table, and the candidate must be that
    // table. A live sibling confirms rather than disputes; the live
    // table itself grants only through the live-return leg, never here.
    let mut static_tables = scanned
        .tables
        .iter()
        .enumerate()
        .filter(|(_, table)| !table.live_return);
    let Some((position, _)) = static_tables.next() else {
        return false;
    };
    if static_tables.next().is_some() || index != position || !scan_finished {
        return false;
    }
    if scanned
        .interfaces
        .iter()
        .any(|interface| interface.table == Some(index) && interface.name_class != "exact_standard")
    {
        return false;
    }
    let table = &scanned.tables[index];
    if published_walk(index, &scanned.tables, &scanned.interfaces, exports) != "full" {
        return false;
    }
    // The clause-1 core, re-proven inside this stricter predicate so
    // the verified-forward exemption lives in exactly one place.
    if module.witness_fault || !standard_layout_core(module, index) {
        return false;
    }
    // A 3.x getter beside a 2.x table refutes the legacy-prefix reading
    // (a wider table may be reachable through it); beside a full 3.x
    // table the table's own extent answers that concern.
    if module.getter_present && table.version.0 == 2 {
        return false;
    }
    let present: BTreeSet<&str> = table.entries.iter().map(|entry| entry.name).collect();
    if !SOLE_COMPLETE_REQUIRED_2X
        .iter()
        .all(|name| present.contains(name))
    {
        return false;
    }
    if !module
        .exports
        .iter()
        .any(|(name, _)| name == "C_GetFunctionList" || name == "C_GetInterface")
    {
        return false;
    }
    if scanned.double_loaded || scanned.same_file_loads != 1 {
        return false;
    }
    score.exports
}

/// Sole-complete-table scan authority (no-manifest key operations):
/// a single static 2.x table with no static rival proves the table a
/// caller reaches without interface linkage. All five legs hold or
/// nothing grants; anything else stays refused. Leg (a) needs a
/// finished tables scan: a truncated scan that found one table proves
/// nothing about a second it never reached. Live siblings are not
/// rivals (the observed return confirms); the live table itself grants
/// only through the live-return leg.
fn sole_complete_table_authorized(
    module: &ReconciledModule,
    index: usize,
    exports: &ObjectExports<'_>,
    scan_finished: bool,
) -> bool {
    let scanned = &module.scanned;
    // Live tables are runtime observations, never scan rivals: the leg
    // needs exactly one static table, and the candidate must be that
    // table. A live sibling confirms rather than disputes; the live
    // table itself grants only through the live-return leg, never here.
    let mut static_tables = scanned
        .tables
        .iter()
        .enumerate()
        .filter(|(_, table)| !table.live_return);
    let Some((position, _)) = static_tables.next() else {
        return false;
    };
    if static_tables.next().is_some() || index != position {
        return false;
    }
    if !scan_finished {
        return false;
    }
    if scanned
        .interfaces
        .iter()
        .any(|interface| interface.table == Some(index) && interface.name_class != "exact_standard")
    {
        return false;
    }
    let table = &scanned.tables[index];
    if published_walk(index, &scanned.tables, &scanned.interfaces, exports) != "full" {
        return false;
    }
    if table.decoded_slot_count() != 68 {
        return false;
    }
    // The 3.x leg is sound: `extension_impossible` proves the full declared
    // extent was readable with the first structural failure in 68..92,
    // refuting the 92/104-wide layouts, so the 68-slot legacy prefix is the
    // complete reachable surface (see `proven_complete_legacy_prefix`).
    if !(table.version.0 == 2 || (table.version.0 == 3 && table.extension_impossible)) {
        return false;
    }
    if module.getter_present || module.witness_fault {
        return false;
    }
    // The clause-1 core, re-proven inside this stricter predicate so
    // the verified-forward exemption lives in exactly one place. The
    // 68-slot shape above implies the core's shape check.
    if !standard_layout_core(module, index) {
        return false;
    }
    let present: BTreeSet<&str> = table.entries.iter().map(|entry| entry.name).collect();
    if !SOLE_COMPLETE_REQUIRED_2X
        .iter()
        .all(|name| present.contains(name))
    {
        return false;
    }
    if !module
        .exports
        .iter()
        .any(|(name, _)| name == "C_GetFunctionList")
    {
        return false;
    }
    if scanned.double_loaded || scanned.same_file_loads != 1 {
        return false;
    }
    // No unresolved-lookalike count is needed here: (a) above already
    // requires exactly one static table, and a closure array needs more
    // than `MAX_TABLES_PER_OBJECT` unresolved tables, so any second
    // static candidate — exports-only or otherwise — refuses at the (a)
    // gate. Live siblings are observations, not candidates.
    true
}

/// Scan lowering with standard-layout semantic authority (owner
/// 2026-11-11: no manifest needed for standard providers): targets of
/// name-authorized tables whose standard layout is proven by scan-time
/// evidence the observer already has — exact interface linkage (the
/// provider's own "PKCS 11" static data names this table), the
/// sole-complete-table leg (KO-SOLE), a typed-getter export with full
/// per-ordinal export agreement, or an observed typed-getter return —
/// carry semantic authority in every lowering, so profile/trace
/// attribute mechanism ids without --manifest. A stale manifest's
/// fallback proof lends names only, never semantics (controller
/// 2026-11-12 05:25). The
/// live-return leg runs in every lowering: the subset takes any
/// core-passing return (heap-first tables), while the main plan only
/// takes a return that confirms the provider's own exports per-ordinal.
/// A late return cannot upgrade a frozen attached slot, but denying a
/// confirming return after the scan legs granted downgrades attached
/// semantic slots to count-only, churning every capture with an observed
/// return through a detach+reattach static episode. Exact exports
/// agreement stays names-only here; the per-ordinal exports leg is a
/// follow-up. Unknown or vendor-shifted tables stay count-only.
fn lower_scanned_with(module: &ReconciledModule, scan_authorized: bool) -> Discovered<'_> {
    let scanned = &module.scanned;
    // The module object's own `.dynsym`: the export-linkage witness for
    // every table this module published.
    let exports = ObjectExports {
        object: scanned.key,
        symbols: &module.exports,
        getter_present: module.getter_present,
        witness_fault: module.witness_fault,
    };
    let mut tables = Vec::new();
    let mut surfaces = Vec::new();
    let mut targets = Vec::new();
    let mut skipped = Vec::new();
    let mut entries_seen = 0usize;
    for (index, table) in scanned.tables.iter().enumerate() {
        // CKF_INTERFACE_FORK_SAFE is bit 0. A table no standard interface exposes
        // is never assumed fork-safe.
        let fork_safe = scanned.interfaces.iter().any(|interface| {
            interface.table == Some(index)
                && interface.name_class == "exact_standard"
                && interface.flags & 1 != 0
        });
        // Every record the scan decoded, including the ones no probe can reach:
        // "seen" must not shrink because a target turned out to be unusable,
        // or `slots` vs `table_entries` stops reading as attached vs seen.
        let published = table.entries.len() + table.null_entries.len() + table.unpinned.len();
        entries_seen += published;
        // Same score inputs `merge` admits by, so provenance, the heuristic
        // cap, and name authorization can never disagree about one table.
        let score = table_evidence_score(
            index,
            &scanned.tables,
            &scanned.interfaces,
            &[],
            &[],
            &exports,
        );
        let authorized = table_name_authorized(&score);
        // Semantic eligibility is name authorization with the manifest
        // contribution removed (controller ruling 2026-11-12 05:25): a
        // stale fallback proof lends names only, so a granting arm
        // additionally needs independent publication evidence —
        // linkage, a live return, or full export agreement. The sole
        // leg proves layout from scan structure alone, so without this
        // gate a stale-backed exports-disagreeing replacement would
        // authorize 68/68 semantic slots while the same replacement
        // without stale support stays count-only.
        let semantic_eligible = table_name_authorized(&TableEvidenceScore {
            manifest: false,
            ..score
        });
        // Argument-read (semantic) authority from a scan needs the
        // table's standard layout proven by scan-time evidence
        // (controller ruling 2026-11-11 clause 1): the version field
        // matches the decoded slot count and every retained entry
        // points into the provider's own object, plus at least one of
        // exact "PKCS 11" interface linkage, the sole-complete-table
        // leg, a typed-getter export with full per-ordinal export
        // agreement (the table reached through the provider's own
        // exports), or an observed typed-getter return (the main plan
        // additionally requires per-ordinal export confirmation; the
        // subset takes heap-first returns). A stale manifest's
        // fallback proof (`manifest_supported`, the only source of
        // `score.manifest` here — every caller passes empty manifest
        // offsets) lends NAME authority so the proof completes in the
        // plan, but never semantic authority: the stale manifest's
        // entries are outdated by definition, so no slot may be
        // authorized because of them (controller ruling 2026-11-12
        // 05:25). A replacement that proves the standard layout from
        // its OWN scan evidence keeps exactly the authority it would
        // have with no manifest at all.
        // Unknown or vendor-shifted tables stay count-only: no
        // argument is ever read through an unproven slot.
        // Every leg is gated once by the clause-1 core
        // (`standard_layout_core`: version-consistent slot count,
        // every retained entry in the provider's own object, and no
        // unpinned non-NULL slot), hoisted into the first condition
        // below so no present or future leg can grant authority on
        // its evidence alone; the sole-complete and getter-export
        // predicates additionally re-prove it inside their stricter
        // checks. The getter-export leg generalizes the sole leg
        // past 68 slots under the same ambient guards (see
        // `getter_export_authorized`).
        // The static legs read finished-ness from the parameter so the
        // re-proof below can reuse what they would grant on a finished
        // scan; the grant itself additionally requires the real flag, so
        // an unfinished scan grants nothing here.
        let scan_finished = scanned.tables_scan_finished;
        let sole_proven = sole_complete_table_authorized(module, index, &exports, true);
        let getter_proven = getter_export_authorized(module, index, &exports, &score, true);
        let standard_layout_evidence = if !semantic_eligible || !standard_layout_core(module, index)
        {
            None
        } else if score.linked {
            Some("interface linkage")
        } else if scan_finished && sole_proven {
            Some("sole complete table")
        } else if scan_finished && getter_proven {
            Some("typed getter export")
        } else if score.live_return && (scan_authorized || score.exports) {
            // The subset takes any core-passing return (heap-first
            // tables); the main plan only takes a return that
            // confirms the provider's own exports per-ordinal — the
            // observed table a caller reaches. Denying a confirming
            // return after the scan legs granted churns the capture
            // through a detach+reattach static episode, while a
            // non-confirming (heap-novel, forged-name) return keeps
            // no layout proof and stays count-only.
            Some("typed getter return")
        } else {
            None
        };
        // Re-proof, not a grant: no leg granted, the scan is unfinished,
        // and a static leg would grant this same table on a finished
        // scan. `extend_exact_prepared` may carry a verified basis across
        // exactly this transient; forged, rivaled or otherwise unproven
        // tables fail the assumed-finished legs and stay refused.
        // Carry permission passes the same manifest-free eligibility
        // test as every grant (ruling 05:25): a stale fallback lends
        // names only, so a stale-backed disagreeing replacement re-proves
        // nothing and the merge still replaces into count-only.
        let reproven_unfinished = semantic_eligible
            && standard_layout_evidence.is_none()
            && !scan_finished
            && (sole_proven || getter_proven);
        let scan_semantic = semantic_eligible && standard_layout_evidence.is_some();
        tables.push(TableSummary {
            version: table.version,
            entries: table.entries.len(),
            source: "scan",
            file_offset: table.file_offset,
            linkage: table_linkage(&score),
            exports_agreeing: Some(export_agreement(table, &exports).agreeing),
        });
        // A 68-slot prefix proven to be the complete reachable surface
        // reports a full walk: every function a conforming caller can
        // reach was walked. The source still names the declared 3.x
        // version, so the mislabelling quirk stays visible. A table an
        // interface record links keeps the raw decoder walk: one table
        // never publishes both `full` and `known_prefix`.
        let walk = published_walk(index, &scanned.tables, &scanned.interfaces, &exports);
        surfaces.push(SurfaceSummary {
            source: format!(
                "{} table {}.{}",
                scanned.path, table.version.0, table.version.1
            ),
            walk: walk.to_string(),
            // The bytes were read straight out of the target's mapping.
            acquisition: "ok".into(),
            functions: published,
        });
        surfaces.extend(
            scanned
                .interfaces
                .iter()
                .filter(|interface| interface.table == Some(index))
                .map(|interface| SurfaceSummary {
                    source: format!("interface[{}] {}", interface.index, interface.name_class),
                    walk: table.walk.to_string(),
                    acquisition: "ok".into(),
                    functions: published,
                }),
        );
        targets.extend(
            scanned_table_rows(module, index).map(|(entry, object)| Target {
                name: entry.name,
                object,
                object_path: &entry.object_path,
                file_offset: entry.file_offset,
                fork_safe,
                semantic_authorized: scan_semantic,
                standard_layout_evidence,
                reproven_unfinished,
                name_authorized: authorized,
                unproven: (!authorized).then_some(UnprovenNames::HeuristicTable),
                table: Some(index),
                ordinal: standard_ordinal(entry.name).map(|ordinal| SlotOrdinal {
                    table_file_offset: table.file_offset,
                    ordinal,
                }),
                aliases: if score.exports && entry.object == exports.object {
                    exports.aliases_at(entry.name, entry.file_offset)
                } else {
                    Vec::new()
                },
            }),
        );
        skipped.extend(table.null_entries.iter().map(|name| Skipped {
            subject: presented_name(authorized, name).to_string(),
            reason: "null pointer".into(),
        }));
        // Unpinned subjects are the same ordinal labels (reconciliation records
        // them verbatim), so the same gate applies; the reasons keep the facts.
        skipped.extend(table.unpinned.iter().map(|skip| Skipped {
            subject: presented_name(authorized, &skip.subject).to_string(),
            reason: skip.reason.clone(),
        }));
    }
    Discovered {
        object: module.object,
        key: scanned.key,
        path: &scanned.path,
        module_named: module.scanned.module_hint.is_some(),
        source: "scan",
        tables,
        interfaces: scanned.interfaces.len(),
        surfaces,
        entries_seen,
        targets,
        skipped,
        scan_evidence: Some(ScanEvidence {
            tables: &scanned.tables,
            interfaces: &scanned.interfaces,
            exports,
        }),
    }
}

/// Which `provenance_objects[]` record carries the identity of an `objects[]` record.
/// Matching by equal path and identity first, then by one unique whole-file hash, is
/// what `validate_structure` guarantees. The two paths are *not* the same string in
/// general — `p11scope-discover` writes `objects[].path` as the `--module` argument
/// was spelled and `provenance_objects[].path` as `/proc/self/maps` renders it, which
/// differ for any provider named by symlink. A digest shared by multiple non-path
/// records is incomparable rather than first-wins authority.
///
/// Public because `main.rs::retarget_to_pins` rewrites the record this returns before
/// the plan is built: one relation used by both, rather than two written against
/// different fields, which is exactly how they drifted apart once already.
pub fn provenance_of(m: &Manifest, object: &ObjectRecord) -> Option<usize> {
    if let Some((index, provenance)) = m
        .provenance_objects
        .iter()
        .enumerate()
        .find(|(_, provenance)| provenance.path == object.path)
    {
        return (provenance.identity.sha256 == object.identity.sha256).then_some(index);
    }
    let sha256 = object.identity.sha256.as_deref()?;
    let mut matches = m
        .provenance_objects
        .iter()
        .enumerate()
        .filter(|(_, provenance)| provenance.identity.sha256.as_deref() == Some(sha256));
    let (index, _) = matches.next()?;
    matches.next().is_none().then_some(index)
}

/// The (device, inode) discovery recorded for a manifest object. Identity lives
/// in `provenance_objects`; `objects[]` carries only paths and hashes.
fn object_key(m: &Manifest, object: &ObjectRecord) -> Option<ObjectKey> {
    let provenance = &m.provenance_objects[provenance_of(m, object)?];
    Some(ObjectKey {
        device: Device {
            major: provenance.device_major,
            minor: provenance.device_minor,
        },
        inode: provenance.inode,
    })
}

#[cfg(test)]
fn build(m: &Manifest) -> AttachPlan {
    let mut ids = BTreeMap::new();
    for key in m.objects.iter().filter_map(|object| object_key(m, object)) {
        let next = PinnedObjectId(ids.len() as u32);
        ids.entry(key).or_insert(next);
    }
    let (discovered, orphaned) = lower_manifest(m, |key, _| ids.get(&key).copied(), |_, _| true);
    let mut plan = merge(
        discovered.into_iter().collect(),
        m.vendor_interfaces.len(),
        acquisition_label(&m.interface_list),
        &BTreeMap::new(),
        ExistingAllocation {
            slots: 0,
            active: &BTreeMap::new(),
            revivable: &BTreeMap::new(),
            retired_keys: &BTreeMap::new(),
            retired_slots: &BTreeSet::new(),
            prior_slots: &[],
            prior_identities: &BTreeMap::new(),
            owned: &BTreeMap::new(),
            first_plan: None,
            first_plan_had_provider: false,
        },
        false,
        AdmissionPolicy::detailed(),
        AdmissionScope::Named,
        false,
    );
    plan.skipped.extend(orphaned);
    plan
}

/// Upper-bound plan bytes one manifest code location (a surface function
/// or a located getter) can leave: a count triple and a skip, both sized,
/// since it leaves exactly one of the two.
fn measure_manifest_function(
    measured: &mut usize,
    name: &str,
    resolution: &Resolution,
    module_path: &str,
) -> Result<(), GraphRefusal> {
    // Upper bound: every function leaves both a count triple
    // and a skip (it leaves exactly one of the two).
    plan_add(
        measured,
        plan_bytes_for::<(String, PinnedObjectId, u64)>(1)?,
    )?;
    for _ in 0..3 {
        plan_add(measured, plan_text_bytes(name)?)?;
    }
    plan_add(measured, plan_bytes_for::<Target<'_>>(1)?)?;
    plan_add(measured, plan_tree_bytes::<AttachKey, ()>(1)?)?;
    plan_add(
        measured,
        plan_tree_bytes::<(String, PinnedObjectId, u64, usize), ()>(1)?,
    )?;
    plan_add(
        measured,
        plan_tree_bytes::<(String, PinnedObjectId, u64), usize>(1)?,
    )?;
    let mut reason = name
        .len()
        .checked_add(module_path.len())
        .and_then(|bytes| bytes.checked_add(128))
        .ok_or(GraphRefusal::Overflow)?;
    if let Resolution::UnusableFile { reason: cause, .. } = resolution {
        reason = reason
            .checked_add(cause.len())
            .ok_or(GraphRefusal::Overflow)?;
    }
    let reason = plan_byte_len(reason)?;
    plan_add(measured, plan_bytes_for::<Skipped>(5)?)?;
    for _ in 0..5 {
        plan_add(measured, plan_text_bytes(name)?)?;
        plan_add(measured, reason)?;
    }
    plan_add(measured, plan_tree_bytes::<(String, String), usize>(1)?)?;
    plan_add(
        measured,
        plan_tree_bytes::<(&'static str, String, String, usize), ()>(1)?,
    )?;
    plan_add(
        measured,
        plan_tree_bytes::<(&'static str, String, String, usize), ()>(1)?,
    )?;
    Ok(())
}

fn lower_manifest<'m>(
    m: &'m Manifest,
    mut pinned_id: impl FnMut(ObjectKey, &str) -> Option<PinnedObjectId>,
    mut compatible: impl FnMut(PinnedObjectId, PinnedObjectId) -> bool,
) -> (Option<Discovered<'m>>, Vec<Skipped>) {
    let mut tables = Vec::new();
    let mut surfaces = Vec::new();
    let mut targets = Vec::new();
    let mut skipped = Vec::new();
    let mut entries_seen = 0usize;

    // One lowering for every resolved code location the manifest names:
    // walked-surface functions and located getters alike.
    let mut lower_one = |name: &'m String,
                         resolution: &'m Resolution,
                         fork_safe: bool,
                         semantic_authorized: bool| {
        entries_seen += 1;
        let mut skip = |reason: String| {
            skipped.push(Skipped {
                subject: name.clone(),
                reason,
            })
        };
        match resolution {
            Resolution::Resolved {
                object,
                file_offset,
            } => {
                let Some(record) = m.objects.iter().find(|o| o.id == *object) else {
                    skip(format!("object id {object} missing from manifest"));
                    return;
                };
                let Some(key) = object_key(m, record) else {
                    skip(format!(
                        "object id {object} has no provenance record naming {}",
                        record.path
                    ));
                    return;
                };
                let Some(object) = pinned_id(key, &record.path) else {
                    skip(format!(
                        "object id {object} has no comparable pinned identity"
                    ));
                    return;
                };
                if let Some(provider) = m
                    .objects
                    .iter()
                    .find(|candidate| candidate.path == m.module_path)
                    .and_then(|candidate| {
                        object_key(m, candidate).and_then(|key| pinned_id(key, &candidate.path))
                    })
                    && !compatible(provider, object)
                {
                    skip(format!(
                        "object id {} has a different target ABI from the provider",
                        record.id
                    ));
                    return;
                }
                targets.push(Target {
                    name,
                    table: None,
                    ordinal: standard_ordinal(name).map(|ordinal| SlotOrdinal {
                        table_file_offset: None,
                        ordinal,
                    }),
                    aliases: Vec::new(),
                    object,
                    object_path: &record.path,
                    file_offset: *file_offset,
                    fork_safe,
                    semantic_authorized,
                    standard_layout_evidence: None,
                    reproven_unfinished: false,
                    name_authorized: true,
                    unproven: None,
                });
            }
            Resolution::NullPointer => skip("null pointer".into()),
            Resolution::NonFileBacked => skip("non-file-backed".into()),
            Resolution::Unmapped => skip("unmapped".into()),
            Resolution::UnusableFile { reason, .. } => skip(reason.clone()),
        }
    };
    for surface in &m.surfaces {
        surfaces.push(SurfaceSummary {
            source: source_label(&surface.source),
            walk: crate::manifest_input::effective_surface_walk(surface),
            acquisition: acquisition_label(&surface.acquisition),
            functions: surface.functions.len(),
        });
        tables.push(TableSummary {
            version: surface
                .version
                .map_or((0, 0), |version| (version.major, version.minor)),
            entries: surface.functions.len(),
            source: "manifest",
            file_offset: None,
            linkage: "manifest",
            exports_agreeing: None,
        });
        let fork_safe = matches!(
            &surface.source,
            SurfaceSource::Interface { flags, .. } if flags & 1 != 0
        );
        for f in &surface.functions {
            lower_one(&f.name, &f.resolution, fork_safe, true);
        }
    }

    // Located getters lower like function records (each counts its own
    // calls under its standard name); the observer reads the tables they
    // return at run time. They lower count-only: no walked table proves
    // their layout here, and the live table that later holds the same
    // getter is count-only too. A scanned table of the program object may
    // give the shared slot a count-only descriptor; when that table
    // retires, the merge keeps the descriptor rather than replacing the
    // probe (see `count_only_same`). A getter a walked surface already
    // records at the same place lowers once.
    for getter in &m.getters {
        let recorded = m
            .surfaces
            .iter()
            .flat_map(|surface| &surface.functions)
            .any(|function| function.name == getter.name);
        if !recorded {
            lower_one(&getter.name, &getter.resolution, false, false);
        }
    }
    let key = m
        .objects
        .iter()
        .find(|o| o.path == m.module_path)
        .and_then(|o| object_key(m, o));
    let Some(key) = key else {
        return (None, skipped);
    };
    let Some(module_record) = m.objects.iter().find(|o| o.path == m.module_path) else {
        return (None, skipped);
    };
    let Some(module_object) = pinned_id(key, &module_record.path) else {
        return (None, skipped);
    };

    // Selection activation remains a separate count-only path. Keep its
    // observation and target-admission gaps visible in the ordinary summary.
    let mut selection_gaps = Vec::new();
    for table in &m.selection_evidence.tables {
        if crate::manifest_input::selection_table_inventory_incomplete(&m.selection_evidence, table)
        {
            selection_gaps.push(Skipped {
                subject: format!("selection table {}", table.id),
                reason: format!(
                    "partial function inventory; {} words observed",
                    table.functions.len()
                ),
            });
        }
        for (ordinal, function) in table.functions.iter().enumerate() {
            let reason = match &function.resolution {
                Resolution::Resolved { object, .. } => {
                    match m.objects.iter().find(|record| record.id == *object) {
                        None => Some(format!("object id {object} missing from manifest")),
                        Some(record) => match object_key(m, record)
                            .and_then(|key| pinned_id(key, &record.path))
                        {
                            None => Some(format!(
                                "object id {object} has no comparable pinned identity"
                            )),
                            Some(target) if !compatible(module_object, target) => Some(format!(
                                "object id {object} has a different target ABI from the provider"
                            )),
                            Some(_) => None,
                        },
                    }
                }
                Resolution::NullPointer => None,
                Resolution::NonFileBacked => Some("non-file-backed".into()),
                Resolution::Unmapped => Some("unmapped".into()),
                Resolution::UnusableFile { reason, .. } => Some(reason.clone()),
            };
            if let Some(reason) = reason {
                selection_gaps.push(Skipped {
                    subject: format!("selection table {} ordinal {ordinal}", table.id),
                    reason,
                });
            }
        }
    }

    (
        Some(Discovered {
            object: module_object,
            // Informational only: every target carries the key of the object it
            // resolved into, which for a forwarded entry is a dependency, not this.
            key,
            path: &m.module_path,
            module_named: false,
            source: "manifest",
            tables,
            interfaces: m
                .surfaces
                .iter()
                .filter(|s| matches!(s.source, SurfaceSource::Interface { .. }))
                .count(),
            surfaces,
            entries_seen,
            targets,
            skipped,
            scan_evidence: None,
        }),
        selection_gaps,
    )
}

/// Lowers one resolved `--prearm-module` piece (packet 6.13, R2-D1-1/2).
/// Operator-side like a manifest piece (`scan_evidence: None`: admitted
/// whole under the unchanged caps), but with no tables, no interfaces and
/// no surfaces — a pre-arm input proves offsets, never tables. Targets
/// carry file-derived names, so they read operator-side like manifest
/// names; file selection is not attestation, so they stay count-only
/// unless an independently accepted manifest authorizes the same slot.
/// `fork_safe` stays false because no standard interface exposes them.
fn lower_prearm(piece: &PrearmPlanPiece) -> Discovered<'_> {
    let mut targets = Vec::new();
    let mut skipped = Vec::new();
    for (name, file_offset) in &piece.proved {
        targets.push(Target {
            name,
            object: piece.object,
            object_path: &piece.path,
            file_offset: *file_offset,
            fork_safe: false,
            semantic_authorized: false,
            standard_layout_evidence: None,
            reproven_unfinished: false,
            name_authorized: true,
            unproven: None,
            table: None,
            ordinal: standard_ordinal(name).map(|ordinal| SlotOrdinal {
                table_file_offset: None,
                ordinal,
            }),
            aliases: Vec::new(),
        });
    }
    for (name, file_offset) in &piece.non_executable {
        skipped.push(Skipped {
            subject: name.clone(),
            reason: format!(
                "{name}+{file_offset:#x} is outside every executable ELF segment; \
                 pre-arm attaches it only after ordinary scan corroboration"
            ),
        });
    }
    Discovered {
        object: piece.object,
        key: piece.key,
        path: &piece.path,
        module_named: false,
        source: "prearm",
        tables: Vec::new(),
        interfaces: 0,
        surfaces: Vec::new(),
        entries_seen: targets.len() + skipped.len(),
        targets,
        skipped,
        scan_evidence: None,
    }
}

/// Operator-declared attach keys per module object (packet 6.13, R2-D1-2/4):
/// manifest-claimed targets plus pre-arm export-proved targets, grouped by
/// the publishing module's object. Scan-decoded targets are never declared:
/// unproved functions attach only after ordinary scan corroboration. The
/// engine freezes this map's pre-arm entries as each watch's declared
/// endpoint set; an empty set means `unavailable`, never armed.
pub(crate) fn operator_target_keys(
    manifests: &[Manifest],
    prearm: &[PrearmPlanPiece],
    pinned: &PinnedObjects,
) -> BTreeMap<PinnedObjectId, BTreeSet<AttachKey>> {
    let (mut pinned_id, mut compatible) = pinned_manifest_lookups(pinned);
    let mut declared: BTreeMap<PinnedObjectId, BTreeSet<AttachKey>> = BTreeMap::new();
    for manifest in manifests {
        let (piece, _) = lower_manifest(manifest, &mut pinned_id, &mut compatible);
        if let Some(piece) = &piece {
            declared
                .entry(piece.object)
                .or_default()
                .extend(piece.targets.iter().map(|target| AttachKey {
                    object: target.object,
                    file_offset: target.file_offset,
                }));
        }
    }
    for piece in prearm {
        declared
            .entry(piece.object)
            .or_default()
            .extend(piece.proved.iter().map(|(_, file_offset)| AttachKey {
                object: piece.object,
                file_offset: *file_offset,
            }));
    }
    declared
}

/// Conservative plan cursor: removal-only rebuild of an [`AttachPlan`] from
/// surviving sources, one bounded step per credit.
///
/// The cursor never grows: output slots are a subset of the old plan's, and
/// output modules are the already-admitted groups rebuilt from the surviving
/// sources. A slot survives exactly when a surviving source row still yields
/// its exact key (through the shared [`lower_scanned`]/[`lower_manifest`]
/// lowering), or when it is a provisional seed whose object still has an
/// admitted group (the rebuilt carry loop's module check). Everything else
/// retires in place. Growth in the sources (new keys, new groups) is ignored:
/// the delta's `new`/`replace` stay empty and historical refusals are kept.
///
/// Output assembly mirrors [`AttachPlan::extend_exact_prepared`]'s removal
/// path (retired slots stay in place with unchanged content, aggregate owners
/// merge the same way, retire rows leave in key order), and module summaries,
/// skips and surfaces replicate merge's per-group build (same dedup rules)
/// over the surviving groups, so a removal-only derivation equals the
/// rebuild-then-extend reference field for field. Admission is deliberately
/// not replicated: surviving groups were admitted under a tighter budget, so
/// they stay admitted; capacity refusals, spill counts and the broad-admit
/// flag affect only evidence the cursor carries over (see `assemble`). The
/// known divergences from a full rebuild are all growth-shaped (new slots,
/// resurrected retired keys, shared-target name narrowing, re-refusal reason
/// strings) and resolve to no-growth by design.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub(crate) struct PlanFence {
    token: u64,
    mutations: u64,
    slots: usize,
    modules: usize,
    skipped: usize,
}

// consumed by T4: the fence runs only inside the cursor poll.
#[allow(dead_code)]
impl PlanFence {
    /// Snapshots the fenced members. A poisoned token refuses at once, before
    /// any derivation step runs.
    pub(crate) fn snapshot(plan: &AttachPlan) -> Result<Self, GraphRefusal> {
        if plan.token.0 == PLAN_TOKEN_POISON {
            return Err(GraphRefusal::SourceChanged);
        }
        Ok(Self {
            token: plan.token.0,
            mutations: plan.mutations.0,
            slots: plan.slots.len(),
            modules: plan.modules.len(),
            skipped: plan.skipped.len(),
        })
    }

    pub(crate) fn check(&self, plan: &AttachPlan) -> Result<(), GraphRefusal> {
        if Self::snapshot(plan)? == *self {
            Ok(())
        } else {
            Err(GraphRefusal::SourceChanged)
        }
    }
}

/// Byte accounting mirrors `discovery::identity`'s conservative-copy
/// accounting, which is private to that module: every owned allocation below
/// is covered by the one measured reservation before it happens.
// consumed by T4: used only by the cursor measure phase.
#[allow(dead_code)]
fn plan_bytes_for<T>(count: usize) -> Result<usize, GraphRefusal> {
    count
        .checked_mul(std::mem::size_of::<T>())
        .and_then(|bytes| bytes.checked_add(OWNED_ALLOCATION_PADDING))
        .ok_or(GraphRefusal::Overflow)
}

// consumed by T4: used only by the cursor measure phase.
#[allow(dead_code)]
fn plan_byte_len(len: usize) -> Result<usize, GraphRefusal> {
    len.checked_add(OWNED_ALLOCATION_PADDING)
        .ok_or(GraphRefusal::Overflow)
}

// consumed by T4: used only by the cursor measure phase.
#[allow(dead_code)]
fn plan_text_bytes(text: &str) -> Result<usize, GraphRefusal> {
    plan_byte_len(text.len())
}

// consumed by T4: used only by the cursor measure phase.
// Rust 1.99.1 B=6 BTree keeps every non-root node at >=5 keys, so n entries
// need at most 1+(n-1)/5 nodes; empty maps allocate nothing. Node size is the
// full internal size applied to every node.
#[allow(dead_code)]
fn plan_tree_bytes<K, V>(entries: usize) -> Result<usize, GraphRefusal> {
    fn align8(bytes: usize) -> Option<usize> {
        bytes.checked_add(7).map(|value| value & !7)
    }
    if std::mem::align_of::<K>() > 8 || std::mem::align_of::<V>() > 8 {
        return Err(GraphRefusal::Overflow);
    }
    let keys = std::mem::size_of::<K>()
        .checked_mul(11)
        .and_then(align8)
        .ok_or(GraphRefusal::Overflow)?;
    let values = std::mem::size_of::<V>()
        .checked_mul(11)
        .and_then(align8)
        .ok_or(GraphRefusal::Overflow)?;
    let node = 16usize
        .checked_add(keys)
        .and_then(|bytes| bytes.checked_add(values))
        .and_then(|bytes| bytes.checked_add(12 * 8))
        .and_then(|bytes| bytes.checked_add(OWNED_ALLOCATION_PADDING))
        .ok_or(GraphRefusal::Overflow)?;
    let nodes = if entries == 0 {
        0
    } else {
        1 + (entries - 1) / 5
    };
    nodes.checked_mul(node).ok_or(GraphRefusal::Overflow)
}

// consumed by T4: used only by the cursor measure phase.
#[allow(dead_code)]
fn plan_add(total: &mut usize, bytes: usize) -> Result<(), GraphRefusal> {
    *total = total.checked_add(bytes).ok_or(GraphRefusal::Overflow)?;
    Ok(())
}

// consumed by T4: used only by the cursor copy/retire phases.
#[allow(dead_code)]
fn next_after<K: Ord + Clone, V: Clone>(map: &BTreeMap<K, V>, after: &Option<K>) -> Option<(K, V)> {
    use std::ops::Bound::{Excluded, Unbounded};
    match after {
        Some(key) => map.range((Excluded(key), Unbounded)).next(),
        None => map.first_key_value(),
    }
    .map(|(key, value)| (key.clone(), value.clone()))
}

