    #[test]
    fn conservative_rebuild_preserves_standard_layout_basis() {
        // N1: the removal-only rebuild copies old slots one-for-one
        // by position, so the standard-layout basis and its evidence
        // labels must survive the install — losing them would read
        // every gated slot as manifest-confirmed.
        use crate::discovery::identity::GraphStep;
        use crate::semantics_edge::resources::SemanticResourcePool;

        let module = sole_complete_module();
        let old = build_from_sources(std::slice::from_ref(&module), &[], &PinnedObjects::empty());
        assert_eq!(old.standard_layout_slot_count(), 68);
        let expected: BTreeMap<AttachKey, bool> = old
            .slots
            .iter()
            .map(|slot| (AttachKey::of(slot), old.is_standard_layout_slot(slot.index)))
            .collect();
        let surviving = [module];
        let pins = PinnedObjects::empty();
        let mut stable = |object: PinnedObjectId| Some(ModuleId(object.0));
        let pool = SemanticResourcePool::default();
        let reserve = pool.reserver();
        let mut cursor = ConservativePlanCursor::new();
        let mut ready = false;
        for _ in 0..10_000 {
            let sources = ConservativePlanSources::new(&surviving, &[], &pins, false);
            match old
                .poll_conservative_rebuild(sources, &mut stable, &mut cursor, &reserve, 256)
                .expect("conservative rebuild of a surviving module")
            {
                GraphStep::Ready => {
                    ready = true;
                    break;
                }
                GraphStep::Advanced | GraphStep::Yielded => {}
            }
        }
        assert!(ready, "the conservative rebuild reaches Ready");
        let rebuilt = cursor.plan().expect("ready cursor holds the rebuilt plan");
        assert_eq!(rebuilt.slots.len(), old.slots.len());
        for slot in &rebuilt.slots {
            assert_eq!(
                rebuilt.is_standard_layout_slot(slot.index),
                expected[&AttachKey::of(slot)],
                "basis follows the slot through the conservative rebuild"
            );
        }
        assert_eq!(rebuilt.standard_layout_slot_count(), 68);
        assert_eq!(
            rebuilt.standard_layout_evidence(),
            old.standard_layout_evidence()
        );
    }

    #[test]
    fn tail_excision_remaps_standard_layout_basis() {
        // N1: excising a tail cell renumbers the survivors; the
        // position-keyed basis set must move with them and drop the
        // excised cell's entry.
        let fixture = counter_history_plan(3);
        let mut base =
            AttachPlan::from_slots_with_policy(fixture.slots, AdmissionPolicy::detailed()).unwrap();
        base.modules = fixture.modules;
        let tail_key = AttachKey::of(&base.slots[2]);

        let mut plan = base.clone();
        plan.standard_layout_slots = BTreeSet::from([2]);
        plan.deactivate(1);
        assert_eq!(
            plan.excise_unlinked_tail_cells(1, &BTreeSet::from([0, 1, 99])),
            [0, u32::MAX, 1]
        );
        assert_eq!(AttachKey::of(&plan.slots[1]), tail_key);
        assert!(
            plan.is_standard_layout_slot(1),
            "the basis follows the renumbered slot"
        );
        assert!(!plan.is_standard_layout_slot(0));
        assert_eq!(plan.standard_layout_slot_count(), 1);

        let mut excised_only = base.clone();
        excised_only.standard_layout_slots = BTreeSet::from([1]);
        excised_only.deactivate(1);
        excised_only.excise_unlinked_tail_cells(1, &BTreeSet::from([1]));
        assert_eq!(
            excised_only.standard_layout_slot_count(),
            0,
            "an excised cell leaves no stale basis behind"
        );
        assert!(!excised_only.is_standard_layout_slot(1));
    }

    #[test]
    fn tail_withdrawal_drops_standard_layout_basis_of_withdrawn_cells() {
        let fixture = counter_history_plan(3);
        let mut plan =
            AttachPlan::from_slots_with_policy(fixture.slots, AdmissionPolicy::detailed()).unwrap();
        plan.modules = fixture.modules;
        plan.standard_layout_slots = BTreeSet::from([2]);
        plan.deactivate(1);
        plan.deactivate(2);
        plan.withdraw_unlinked_additions(1);
        assert_eq!(plan.slots.len(), 1);
        assert_eq!(
            plan.standard_layout_slot_count(),
            0,
            "a withdrawn cell leaves no stale basis for a later occupant"
        );
    }

    #[test]
    fn sync_plan_basis_only_change_keeps_mechanism_rows() {
        // N1: the publication gate is evaluated on every observation
        // and rows carry their own basis flags, so a basis-only plan
        // change must not purge semantic state.
        let module = sole_complete_module();
        let plan = build_from_sources(std::slice::from_ref(&module), &[], &PinnedObjects::empty());
        let sign_init = plan
            .slots
            .iter()
            .find(|slot| slot.names == ["C_SignInit"])
            .expect("C_SignInit slot")
            .index;
        let mut state = crate::semantics::State::new(&plan);
        state.observe(&p11scope_ebpf_common::Event {
            ts_ns: 100,
            duration_ns: 10,
            pid_tgid: 100u64 << 32,
            session: 7,
            mechanism: 0x40, // CKM_SHA256_RSA_PKCS
            rv: 0,
            slot: sign_init,
            capture: p11scope_ebpf_common::capture::MECHANISM_VALUE
                | p11scope_ebpf_common::capture::OUTPUT_NON_NULL,
            target_function: p11scope_ebpf_common::FUNCTION_NONE,
            ..p11scope_ebpf_common::Event::default()
        });
        assert_eq!(
            state.mechanisms().get(&0x40).map(|stat| stat.calls),
            Some(1)
        );
        let mut flipped = plan.clone();
        flipped.standard_layout_slots.clear();
        state.sync_plan(&flipped);
        assert_eq!(
            state.mechanisms().get(&0x40).map(|stat| stat.calls),
            Some(1),
            "a basis-only sync keeps the mechanism rows"
        );
    }

    fn observed_event(slot: u32, mechanism: u64, capture: u32) -> p11scope_ebpf_common::Event {
        p11scope_ebpf_common::Event {
            ts_ns: 100,
            duration_ns: 10,
            pid_tgid: 100u64 << 32,
            session: 7,
            mechanism,
            rv: 0,
            slot,
            capture,
            target_function: p11scope_ebpf_common::FUNCTION_NONE,
            ..p11scope_ebpf_common::Event::default()
        }
    }

    #[test]
    fn rejected_standard_layout_init_never_publishes_via_confirmed_operation() {
        // Mixed authority (per-target merge shape): C_SignInit is
        // standard-layout-only, C_Sign is manifest-confirmed. An
        // unregistered value read at the Init is gated there; the
        // later confirmed operation must not publish it either —
        // publication authority belongs to the slot that read the
        // number, not the slot that later uses the binding.
        let module = sole_complete_module();
        let mut plan =
            build_from_sources(std::slice::from_ref(&module), &[], &PinnedObjects::empty());
        let slot_named = |plan: &AttachPlan, name: &str| {
            plan.slots
                .iter()
                .find(|slot| slot.names == [name])
                .unwrap_or_else(|| panic!("{name} slot"))
                .index
        };
        let sign_init = slot_named(&plan, "C_SignInit");
        let sign = slot_named(&plan, "C_Sign");
        assert!(plan.is_standard_layout_slot(sign_init));
        plan.standard_layout_slots.remove(&sign);
        assert!(!plan.is_standard_layout_slot(sign), "C_Sign confirmed");
        let init_ev = |mechanism: u64, extra: u32| {
            observed_event(
                sign_init,
                mechanism,
                p11scope_ebpf_common::capture::MECHANISM_VALUE
                    | p11scope_ebpf_common::capture::OUTPUT_NON_NULL
                    | extra,
            )
        };
        let sign_ev = || observed_event(sign, 0, p11scope_ebpf_common::capture::OUTPUT_NON_NULL);
        let mut state = crate::semantics::State::new(&plan);
        state.observe(&init_ev(
            0xCE53_43A9,
            p11scope_ebpf_common::capture::MECHANISM_UNREGISTERED,
        ));
        state.observe(&sign_ev());
        assert!(
            !state.mechanisms().contains_key(&0xCE53_43A9),
            "gated Init value keeps no global row after a confirmed operation"
        );
        assert!(
            state
                .cgroups()
                .values()
                .all(|stat| !stat.mechanisms.contains_key(&0xCE53_43A9)),
            "gated Init value keeps no cgroup cell"
        );
        assert!(
            state
                .semantic_evidence()
                .unregistered_standard_layout_mechanisms
                >= 1,
            "the gated value is counted without its number"
        );
        // A withheld Init also replaces any earlier binding: a
        // registered Init followed by a gated Init on the same
        // session must not leave the old mechanism active.
        state.observe(&init_ev(0x40, 0)); // CKM_SHA256_RSA_PKCS
        state.observe(&init_ev(
            0xCE53_43A9,
            p11scope_ebpf_common::capture::MECHANISM_UNREGISTERED,
        ));
        let before = state.mechanisms()[&0x40].calls;
        state.observe(&sign_ev());
        assert_eq!(
            state.mechanisms()[&0x40].calls,
            before,
            "the gated Init replaced the earlier binding"
        );
        assert!(!state.mechanisms().contains_key(&0xCE53_43A9));
    }

    #[test]
    fn confirmed_init_mechanism_still_publishes_via_standard_layout_operation() {
        // Reverse authority: a vendor/unknown value read through a
        // manifest-confirmed Init publishes today and keeps
        // publishing through a later standard-layout operation —
        // the gate follows the reading slot, so confirmed behavior
        // is not silently narrowed.
        let module = sole_complete_module();
        let mut plan =
            build_from_sources(std::slice::from_ref(&module), &[], &PinnedObjects::empty());
        let slot_named = |plan: &AttachPlan, name: &str| {
            plan.slots
                .iter()
                .find(|slot| slot.names == [name])
                .unwrap_or_else(|| panic!("{name} slot"))
                .index
        };
        let sign_init = slot_named(&plan, "C_SignInit");
        let sign = slot_named(&plan, "C_Sign");
        plan.standard_layout_slots.remove(&sign_init);
        assert!(!plan.is_standard_layout_slot(sign_init), "Init confirmed");
        assert!(
            plan.is_standard_layout_slot(sign),
            "operation standard-layout"
        );
        let mut state = crate::semantics::State::new(&plan);
        state.observe(&observed_event(
            sign_init,
            0xCE53_43A9,
            p11scope_ebpf_common::capture::MECHANISM_VALUE
                | p11scope_ebpf_common::capture::OUTPUT_NON_NULL
                | p11scope_ebpf_common::capture::MECHANISM_UNREGISTERED,
        ));
        state.observe(&observed_event(
            sign,
            0,
            p11scope_ebpf_common::capture::OUTPUT_NON_NULL,
        ));
        let stat = state
            .mechanisms()
            .get(&0xCE53_43A9)
            .expect("confirmed Init publishes its vendor mechanism");
        assert_eq!(stat.calls, 2, "Init and operation both recorded");
        assert_eq!(
            state
                .semantic_evidence()
                .unregistered_standard_layout_mechanisms,
            0,
            "nothing was gated: the reading slot was confirmed"
        );
    }

    #[test]
    fn cgroup_mechanism_cells_carry_their_own_attribution_basis() {
        // Per-cgroup basis (review F3): the same mechanism observed
        // through a standard-layout Init in one cgroup and a
        // confirmed Init in another keeps each cgroup's own
        // authority; the merged root row cannot substitute for it.
        let module = sole_complete_module();
        let mut plan =
            build_from_sources(std::slice::from_ref(&module), &[], &PinnedObjects::empty());
        let slot_named = |plan: &AttachPlan, name: &str| {
            plan.slots
                .iter()
                .find(|slot| slot.names == [name])
                .unwrap_or_else(|| panic!("{name} slot"))
                .index
        };
        let sign_init = slot_named(&plan, "C_SignInit");
        let encrypt_init = slot_named(&plan, "C_EncryptInit");
        assert!(plan.is_standard_layout_slot(sign_init));
        plan.standard_layout_slots.remove(&encrypt_init);
        assert!(
            !plan.is_standard_layout_slot(encrypt_init),
            "confirmed Init"
        );
        let mut state = crate::semantics::State::new(&plan);
        let mut standard_ev = observed_event(
            sign_init,
            0x40, // CKM_SHA256_RSA_PKCS
            p11scope_ebpf_common::capture::MECHANISM_VALUE
                | p11scope_ebpf_common::capture::OUTPUT_NON_NULL,
        );
        standard_ev.cgroup_id = 111;
        state.observe(&standard_ev);
        let mut confirmed_ev = observed_event(
            encrypt_init,
            0x40,
            p11scope_ebpf_common::capture::MECHANISM_VALUE
                | p11scope_ebpf_common::capture::OUTPUT_NON_NULL,
        );
        confirmed_ev.cgroup_id = 222;
        state.observe(&confirmed_ev);
        let standard_cell = state.cgroups()[&111].mechanisms[&0x40];
        assert!(standard_cell.attributed_standard_layout);
        assert!(!standard_cell.attributed_confirmed);
        let confirmed_cell = state.cgroups()[&222].mechanisms[&0x40];
        assert!(confirmed_cell.attributed_confirmed);
        assert!(!confirmed_cell.attributed_standard_layout);
        let root = &state.mechanisms()[&0x40];
        assert!(root.attributed_standard_layout && root.attributed_confirmed);
    }

    #[test]
    fn late_verified_frozen_slots_report_as_unverified() {
        // Review F2 (option (c)): a table verified only after probes
        // linked keeps its frozen count-only cookie, so no mechanism
        // can flow; the slot must still report as unverified instead
        // of silently claiming verified coverage.
        let mut early = sole_complete_module();
        early.scanned.tables_scan_finished = false;
        let mut plan =
            build_from_sources(std::slice::from_ref(&early), &[], &PinnedObjects::empty());
        assert!(plan.slots.iter().all(|slot| !slot.semantic_authorized));
        let late = sole_complete_module();
        let rebuilt =
            plan.rebuild_from_sources(std::slice::from_ref(&late), &[], &PinnedObjects::empty());
        assert!(rebuilt.slots.iter().all(|slot| slot.semantic_authorized));
        plan.extend_exact(rebuilt).expect("extend onto frozen plan");
        let frozen = plan
            .slots
            .iter()
            .find(|slot| slot.names == ["C_SignInit"])
            .expect("C_SignInit slot");
        assert!(frozen.semantic_authorized, "userspace verified it late");
        assert_eq!(
            frozen.descriptor_index, 0,
            "but its attach cookie stayed count-only"
        );
        assert_eq!(
            plan.semantic_unverified_slot_count(),
            plan.slots.len(),
            "frozen late-verified slots report as unverified"
        );
    }

