    #[test]
    fn unlinked_scan_label_is_not_a_rival_claim_against_the_manifest() {
        // Task 1.3: an unlinked table's ordinal label carries no information,
        // so it cannot dispute the manifest's operator-authoritative name —
        // `unknown` is transparent, never a rival claim.
        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let manifest = manifest_with(vec![resolved("C_Login", 0x10)]);

        let plan = build_from_test_sources(
            std::slice::from_ref(&scanned),
            std::slice::from_ref(&manifest),
        );

        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, ["C_Login"]);
        assert!(plan.slots[0].semantic_authorized);
        assert_eq!(
            plan.slots[0].semantics,
            crate::kinds::descriptor("C_Login").unwrap()
        );
        assert!(!plan.slots[0].semantic_ambiguous);
    }

    #[test]
    fn linked_scan_label_disputing_the_manifest_stays_count_only() {
        // The safety property the unlinked case retires survives where it has
        // teeth: two AUTHORIZED names disagreeing about one target stay
        // unresolvable, counted but never attributed. The scan side is a
        // full standard-layout linked table (the only linked shape the
        // ruling admits); the manifest disputes its C_Sign target.
        let scanned = interface_linked_module();
        let sign_offset = scanned.scanned.tables[0]
            .entries
            .iter()
            .find(|entry| entry.name == "C_Sign")
            .expect("C_Sign entry")
            .file_offset;
        let manifest = manifest_with(vec![resolved("C_Login", sign_offset)]);

        let plan = build_from_test_sources(
            std::slice::from_ref(&scanned),
            std::slice::from_ref(&manifest),
        );

        let slot = plan
            .slots
            .iter()
            .find(|slot| slot.names == ["C_Login", "C_Sign"])
            .expect("disputed slot");
        // Owner 2026-11-11 (no manifest needed for standard providers):
        // the linked scan claim is now authorized like the manifest
        // claim, so both claims are authorized; the dispute still
        // resolves to count-only through the ambiguous descriptor.
        assert!(slot.semantic_authorized);
        assert_eq!(slot.semantics, SlotSemantics::COUNT_ONLY);
        assert!(slot.semantic_ambiguous);
    }

    #[test]
    fn unlinked_scan_slot_names_its_heuristic_reason() {
        // An unlinked heuristic table proves no publication (no interface
        // linkage, live return, manifest, or export proof), so its slots
        // stay unknown — with the named reason, never a bare unknown.
        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let plan = build_from_test_sources(std::slice::from_ref(&scanned), &[]);

        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, [UNKNOWN_FUNCTION_NAME]);
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::HeuristicTable.token()]
        );
    }

    #[test]
    fn unmatched_selection_slot_names_its_selection_reason() {
        // A selection table no exact-standard v3 query proved stays
        // unknown with the selection reason.
        let object = PinnedObjectId(7);
        let allocated = exact_plan(vec![], vec![exact_module(0, object)]);
        let mut plan = allocated.clone();
        plan.add_selection_table(
            &allocated,
            ModuleId(0),
            [selection_target(object, 0x10, UNKNOWN_FUNCTION_NAME)],
        )
        .unwrap();

        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, [UNKNOWN_FUNCTION_NAME]);
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::SelectionWithoutStandardProof.token()]
        );
    }

    #[test]
    fn selection_claim_on_a_named_sibling_keeps_the_retired_unknown_reason() {
        // With a retired unknown slot and an active named slot sharing
        // one AttachKey, a selection claim that touches the named slot
        // must not strip the unknown sibling's reason: the retired row
        // keeps rendering, so the entry stays for it.
        let object = PinnedObjectId(7);
        let base = exact_plan(vec![], vec![exact_module(0, object)]);
        let candidate = |name: &'static str, file_offset: u64| {
            let mut plan = base.clone();
            let allocated = plan.clone();
            plan.add_selection_table(
                &allocated,
                ModuleId(0),
                [selection_target(object, file_offset, name)],
            )
            .unwrap();
            plan
        };

        let mut plan = candidate(UNKNOWN_FUNCTION_NAME, 0x10);
        plan.extend_exact(candidate(UNKNOWN_FUNCTION_NAME, 0x20))
            .unwrap();
        plan.extend_exact(candidate("C_Login", 0x10)).unwrap();
        assert_eq!(plan.slots.len(), 3);
        assert_eq!(AttachKey::of(&plan.slots[0]), AttachKey::of(&plan.slots[2]));

        let snapshot = plan.clone();
        plan.add_selection_table(
            &snapshot,
            ModuleId(0),
            [selection_target(object, 0x10, "C_Login")],
        )
        .unwrap();
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::SelectionWithoutStandardProof.token()],
            "the retired unknown sibling keeps its reason"
        );
        assert!(
            plan.unnamed_reasons_of(&plan.slots[2]).is_empty(),
            "the named slot still reads no reason"
        );
    }

    #[test]
    fn named_slot_carries_no_unnamed_reason() {
        // Positive twins: a manifest-authorized slot, and a slot where an
        // authorized name displaced `unknown`, carry no reason.
        let manifest = manifest_with(vec![resolved("C_Login", 0x10)]);
        let plan = build_from_test_sources(&[], std::slice::from_ref(&manifest));
        assert_eq!(plan.slots[0].names, ["C_Login"]);
        assert!(plan.unnamed_reasons_of(&plan.slots[0]).is_empty());

        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let manifest = manifest_with(vec![resolved("C_Login", 0x10)]);
        let plan = build_from_test_sources(
            std::slice::from_ref(&scanned),
            std::slice::from_ref(&manifest),
        );
        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, ["C_Login"]);
        assert!(plan.unnamed_reasons_of(&plan.slots[0]).is_empty());
    }

    #[test]
    fn extend_carries_unnamed_reasons_and_drops_them_when_named() {
        // Live rebuilds extend: reasons survive the carry, while a slot
        // the surgery named drops them with `unknown`.
        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let mut plan = build_from_test_sources(std::slice::from_ref(&scanned), &[]);
        let rebuilt = build_from_test_sources(std::slice::from_ref(&scanned), &[]);
        plan.extend_exact(rebuilt).unwrap();
        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, [UNKNOWN_FUNCTION_NAME]);
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::HeuristicTable.token()]
        );

        // Surgery twin: the old authorized name survives a rebuilt
        // unknown, so no reason may linger beside it.
        let manifest = manifest_with(vec![resolved("C_Login", 0x10)]);
        let mut named = build_from_test_sources(&[], std::slice::from_ref(&manifest));
        let rebuilt_unknown = build_from_test_sources(std::slice::from_ref(&scanned), &[]);
        named.extend_exact(rebuilt_unknown).unwrap();
        assert_eq!(named.slots.len(), 1);
        assert_eq!(named.slots[0].names, ["C_Login"]);
        assert!(
            named.unnamed_reasons_of(&named.slots[0]).is_empty(),
            "a slot the surgery named carries no reason"
        );
    }

    #[test]
    fn selection_table_merges_reasons_with_a_retired_same_key_row() {
        // A retired unknown row and a fresh unknown selection slot can
        // share one AttachKey; the fresh claim must union its reason
        // with the retired row's, not replace it.
        let object = PinnedObjectId(7);
        let base = exact_plan(vec![], vec![exact_module(0, object)]);
        let mut plan = base.clone();
        let allocated = plan.clone();
        plan.add_selection_table(
            &allocated,
            ModuleId(0),
            [selection_target(object, 0x10, UNKNOWN_FUNCTION_NAME)],
        )
        .unwrap();
        let key = AttachKey::of(&plan.slots[0]);
        plan.deactivate(0);
        // A scan-discovered sibling proved the same target unproven
        // another way (extend surgery legitimately unions both tokens
        // onto one key; see mixed_unproven_sources_union_their_reasons).
        plan.slot_unnamed_reasons
            .get_mut(&key)
            .expect("the retired unknown row keeps its reason entry")
            .insert(UnprovenNames::HeuristicTable);
        let snapshot = plan.clone();
        plan.add_selection_table(
            &snapshot,
            ModuleId(0),
            [selection_target(object, 0x10, UNKNOWN_FUNCTION_NAME)],
        )
        .unwrap();
        assert_eq!(plan.slots.len(), 2);
        assert_eq!(plan.slots[1].names, [UNKNOWN_FUNCTION_NAME]);
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[1]),
            [
                UnprovenNames::HeuristicTable.token(),
                UnprovenNames::SelectionWithoutStandardProof.token()
            ],
            "the fresh slot unions the retired row's reason with its own claim"
        );
    }

    fn unknown_pair_plan() -> (AttachPlan, AttachKey, AttachKey) {
        // Two unknown slots with distinct reason entries: the survivor
        // and the tail cell the give-backs remove.
        let object = PinnedObjectId(7);
        let mut plan = exact_plan(
            vec![
                exact_slot(0, object, 0x10, 0, vec![ModuleId(0)]),
                exact_slot(1, object, 0x20, 0, vec![ModuleId(0)]),
            ],
            vec![exact_module(0, object)],
        );
        for slot in &mut plan.slots {
            slot.names = vec![UNKNOWN_FUNCTION_NAME.into()];
        }
        let survivor = AttachKey::of(&plan.slots[0]);
        let tail = AttachKey::of(&plan.slots[1]);
        plan.slot_unnamed_reasons
            .insert(survivor, BTreeSet::from([UnprovenNames::HeuristicTable]));
        plan.slot_unnamed_reasons.insert(
            tail,
            BTreeSet::from([UnprovenNames::SelectionWithoutStandardProof]),
        );
        (plan, survivor, tail)
    }

    #[test]
    fn withdraw_unlinked_additions_drops_reasons_for_given_back_cells() {
        // Never-linked tail cells are given back; their reason entries
        // must go with them, while a surviving unknown slot keeps its.
        let (mut plan, survivor, tail) = unknown_pair_plan();
        plan.deactivate(1);
        plan.withdraw_unlinked_additions(1);
        assert_eq!(plan.slots.len(), 1);
        assert!(
            !plan.slot_unnamed_reasons.contains_key(&tail),
            "the given-back cell's reason entry leaves with it"
        );
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::HeuristicTable.token()],
            "the surviving unknown slot keeps its reason"
        );
        assert_eq!(AttachKey::of(&plan.slots[0]), survivor);
    }

    #[test]
    fn excise_unlinked_tail_cells_drops_reasons_for_excised_cells() {
        // A withheld retry's never-linked tail cell is excised; its
        // reason entry must go with it, while a surviving unknown slot
        // keeps its.
        let (mut plan, survivor, tail) = unknown_pair_plan();
        plan.deactivate(1);
        let remap = plan.excise_unlinked_tail_cells(1, &BTreeSet::from([1u32]));
        assert_eq!(plan.slots.len(), 1);
        assert_eq!(remap, [0, u32::MAX]);
        assert!(
            !plan.slot_unnamed_reasons.contains_key(&tail),
            "the excised cell's reason entry leaves with it"
        );
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::HeuristicTable.token()],
            "the surviving unknown slot keeps its reason"
        );
        assert_eq!(AttachKey::of(&plan.slots[0]), survivor);
    }

    #[test]
    fn prune_capture_memory_drops_reasons_with_ordinals() {
        // The capture-memory bound covers reasons exactly like
        // ordinals: a cell the plan no longer holds takes its reason
        // entry with it, while a surviving unknown slot keeps both.
        let (mut plan, survivor, tail) = unknown_pair_plan();
        for (key, ordinal) in [(survivor, 7u16), (tail, 9u16)] {
            plan.slot_ordinals.insert(
                key,
                BTreeSet::from([SlotOrdinal {
                    table_file_offset: None,
                    ordinal,
                }]),
            );
        }
        // Stage the post-excise state: the tail cell is gone.
        plan.slots.pop();
        plan.prune_capture_memory();
        assert!(
            !plan.slot_ordinals.contains_key(&tail),
            "the excised cell's ordinals leave with it"
        );
        assert!(
            !plan.slot_unnamed_reasons.contains_key(&tail),
            "the excised cell's reason entry leaves with it"
        );
        assert_eq!(
            plan.slot_ordinals.get(&survivor).map(BTreeSet::len),
            Some(1),
            "the surviving unknown slot keeps its ordinals"
        );
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [UnprovenNames::HeuristicTable.token()],
            "the surviving unknown slot keeps its reason"
        );
        assert_eq!(AttachKey::of(&plan.slots[0]), survivor);
    }

    #[test]
    fn conservative_cursor_copies_unnamed_reasons() {
        // White-box drive of the cursor's carried-map stages plus
        // assembly: reasons travel like ordinals, whole.
        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let old = build_from_test_sources(std::slice::from_ref(&scanned), &[]);
        assert!(
            !old.slot_unnamed_reasons.is_empty(),
            "precondition: the old plan names a reason"
        );
        let mut cursor = ConservativePlanCursor::new();
        for _ in 0..1_000 {
            if cursor.phase == ConservativePlanPhase::Retire {
                break;
            }
            cursor.copy_one_map_entry(&old).unwrap();
        }
        assert_eq!(cursor.phase, ConservativePlanPhase::Retire);
        cursor.assemble(&old);
        let out = cursor.output.take().expect("assembly produces a plan");
        assert_eq!(out.slot_unnamed_reasons, old.slot_unnamed_reasons);
    }

    #[test]
    fn conservative_rebuild_preserves_unnamed_reasons() {
        // End-to-end drive of `poll_conservative_rebuild` over a
        // nonempty reasons map: the measure/reserve/copy/assemble
        // stages carry the map whole, and the reservation covers it.
        use crate::discovery::identity::GraphStep;
        use crate::semantics_edge::resources::SemanticResourcePool;

        let drive = |old: &AttachPlan, surviving: &[ReconciledModule]| {
            let pins = PinnedObjects::empty();
            let mut stable = |object: PinnedObjectId| Some(ModuleId(object.0));
            let pool = SemanticResourcePool::default();
            let reserve = pool.reserver();
            let mut cursor = ConservativePlanCursor::new();
            let mut ready = false;
            for _ in 0..10_000 {
                let sources = ConservativePlanSources::new(surviving, &[], &pins, false);
                match old
                    .poll_conservative_rebuild(sources, &mut stable, &mut cursor, &reserve, 256)
                    .expect("conservative rebuild of a surviving module")
                {
                    GraphStep::Ready => {
                        ready = true;
                        break;
                    }
                    GraphStep::Advanced | GraphStep::Yielded => {}
                }
            }
            assert!(ready, "the conservative rebuild reaches Ready");
            let rebuilt = cursor
                .plan()
                .expect("ready cursor holds the rebuilt plan")
                .clone();
            let required = cursor.required_bytes().expect("measure completed");
            (rebuilt, required)
        };

        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let old = build_from_test_sources(std::slice::from_ref(&scanned), &[]);
        assert_eq!(old.slots.len(), 1);
        assert_eq!(old.slots[0].names, [UNKNOWN_FUNCTION_NAME]);
        assert!(
            !old.slot_unnamed_reasons.is_empty(),
            "precondition: the old plan names a reason"
        );
        let surviving = [scanned];
        let (rebuilt, required) = drive(&old, &surviving);
        assert_eq!(rebuilt.slots.len(), old.slots.len());
        assert_eq!(
            rebuilt.slot_unnamed_reasons, old.slot_unnamed_reasons,
            "reasons survive the conservative rebuild"
        );
        for slot in &rebuilt.slots {
            assert!(
                !rebuilt.unnamed_reasons_of(slot).is_empty(),
                "the rebuilt unknown slot still reports its reason"
            );
        }
        // The twin differs only in the cleared map, so a larger
        // reservation proves the measure stage charges the map.
        let mut stripped = old.clone();
        stripped.slot_unnamed_reasons.clear();
        let (_, stripped_required) = drive(&stripped, &surviving);
        assert!(
            required > stripped_required,
            "the reservation covers the reasons map: {required} > {stripped_required}"
        );
    }

    #[test]
    fn mixed_unproven_sources_union_their_reasons() {
        // A slot claimed by both an unlinked scan table and an unmatched
        // selection table carries both reasons, sorted.
        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let mut plan = build_from_test_sources(std::slice::from_ref(&scanned), &[]);
        assert_eq!(plan.slots[0].names, [UNKNOWN_FUNCTION_NAME]);
        let module = plan.modules[0].clone();
        let allocated = plan.clone();
        plan.add_selection_table(
            &allocated,
            module.id,
            [SelectionTableTarget::provider_local(
                module.object,
                "/opt/p11.so".into(),
                0x10,
                UNKNOWN_FUNCTION_NAME,
            )],
        )
        .unwrap();

        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, [UNKNOWN_FUNCTION_NAME]);
        assert_eq!(
            plan.unnamed_reasons_of(&plan.slots[0]),
            [
                UnprovenNames::HeuristicTable.token(),
                UnprovenNames::SelectionWithoutStandardProof.token(),
            ]
        );
    }

    fn prearm_piece(proved: Vec<(String, u64)>) -> PrearmPlanPiece {
        PrearmPlanPiece {
            object: TEST_PINNED_OBJECT,
            key: TEST_OBJECT,
            path: "/opt/p11.so".into(),
            proved,
            non_executable: Vec::new(),
        }
    }

    fn build_with_prearm(
        scanned: &[ReconciledModule],
        manifests: &[Manifest],
        prearm: &[PrearmPlanPiece],
    ) -> AttachPlan {
        build_from_sources_with(
            scanned,
            manifests,
            prearm,
            |key, _| u32::try_from(key.inode).ok().map(PinnedObjectId),
            |_, _| true,
            None,
            None,
            ExistingAllocation {
                slots: 0,
                active: &BTreeMap::new(),
                revivable: &BTreeMap::new(),
                retired_keys: &BTreeMap::new(),
                retired_slots: &BTreeSet::new(),
                prior_slots: &[],
                prior_identities: &BTreeMap::new(),
                owned: &BTreeMap::new(),
                first_plan: None,
                first_plan_had_provider: false,
            },
            false,
            AdmissionPolicy::detailed(),
            AdmissionScope::Named,
            false,
        )
    }

    #[test]
    fn bare_prearm_stays_count_only_without_manifest_authority() {
        // File selection is not attestation: export-proved targets stay
        // named but count-only until an accepted manifest supplies authority.
        let plan = build_with_prearm(&[], &[], &[prearm_piece(vec![("C_SignInit".into(), 0x10)])]);
        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, ["C_SignInit"]);
        assert_eq!(plan.slots[0].descriptor_index, 0);
        assert_eq!(plan.slots[0].semantics, SlotSemantics::COUNT_ONLY);
        assert!(!plan.slots[0].semantic_authorized);
    }

    #[test]
    fn manifest_backed_prearm_keeps_semantic_authority() {
        // Positive twin: the same export plus an accepted manifest claim
        // for the same object authorizes the descriptor.
        let manifest = manifest_with(vec![resolved("C_SignInit", 0x10)]);
        let plan = build_with_prearm(
            &[],
            std::slice::from_ref(&manifest),
            &[prearm_piece(vec![("C_SignInit".into(), 0x10)])],
        );
        assert_eq!(plan.slots.len(), 1);
        assert!(plan.slots[0].semantic_authorized);
        assert_ne!(plan.slots[0].descriptor_index, 0);
        assert_eq!(
            plan.slots[0].semantics,
            crate::kinds::descriptor("C_SignInit").unwrap()
        );
    }

    fn inventory_budget_for_prearm_test(endpoints: u64) -> crate::capacity::InventoryBudget {
        crate::capacity::InventoryBudget::new(endpoints, endpoints * 8).unwrap()
    }

    #[test]
    fn inventory_policy_with_prearm_plans_proved_offsets_count_only() {
        // Proved pre-arm offsets lower into an Inventory-policy plan like
        // manifest-side operator input: count-only without
        // independent manifest authority, carrying the Inventory admission
        // policy the inventory attach set requires.
        let budget = inventory_budget_for_prearm_test(4096);
        let plan = build_from_sources_for_policy_scoped_with_prearm(
            &[],
            &[],
            &[prearm_piece(vec![("C_SignInit".into(), 0x10)])],
            &PinnedObjects::empty(),
            AdmissionPolicy::Inventory(budget),
            AdmissionScope::Shared,
        );
        assert_eq!(plan.admission_policy(), AdmissionPolicy::Inventory(budget));
        assert_eq!(plan.refused_modules().count(), 0);
        assert_eq!(plan.slots.len(), 1);
        assert_eq!(plan.slots[0].names, ["C_SignInit"]);
        assert_eq!(plan.slots[0].file_offset, 0x10);
        assert_eq!(plan.slots[0].descriptor_index, 0);
        assert_eq!(plan.slots[0].semantics, SlotSemantics::COUNT_ONLY);
        assert!(!plan.slots[0].semantic_authorized);
        assert!(plan.is_active(plan.slots[0].index));
        plan.validate_slot_index().unwrap();
    }

    #[test]
    fn inventory_policy_with_empty_prearm_builds_the_old_plan() {
        // Additive-only: an empty pre-arm slice builds exactly the plan the
        // old entry builds — every non-pre-arm capture is untouched.
        let scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let manifest = manifest_with(vec![resolved("C_Sign", 0x10)]);
        let policy = AdmissionPolicy::Inventory(inventory_budget_for_prearm_test(4096));
        let old = build_from_sources_for_policy_scoped(
            std::slice::from_ref(&scanned),
            std::slice::from_ref(&manifest),
            &PinnedObjects::empty(),
            policy,
            AdmissionScope::Shared,
        );
        let new = build_from_sources_for_policy_scoped_with_prearm(
            std::slice::from_ref(&scanned),
            std::slice::from_ref(&manifest),
            &[],
            &PinnedObjects::empty(),
            policy,
            AdmissionScope::Shared,
        );
        assert_eq!(old, new);
    }

    #[test]
    fn inventory_policy_prearm_beyond_budget_is_refused_not_admitted() {
        // No admission-cap change: proved offsets compete within the
        // Inventory budget; past it the module is refused whole, never
        // silently admitted beyond the cap.
        let budget = inventory_budget_for_prearm_test(4096);
        let proved: Vec<(String, u64)> = (0..5000u64)
            .map(|index| (format!("C_Extra{index:04}"), 0x10 + index * 8))
            .collect();
        let plan = build_from_sources_for_policy_scoped_with_prearm(
            &[],
            &[],
            &[prearm_piece(proved)],
            &PinnedObjects::empty(),
            AdmissionPolicy::Inventory(budget),
            AdmissionScope::Shared,
        );
        assert_eq!(plan.refused_modules().count(), 1);
        assert!(plan.slots.is_empty());
    }

    #[test]
    fn raw_key_cannot_authorize_a_distinct_pinned_object() {
        let mut scanned = scanned_with(TEST_OBJECT, "/opt/p11.so", [0x10]);
        let scanned_object = PinnedObjectId(200);
        scanned.object = scanned_object;
        scanned.entry_objects[0][0] = scanned_object;
        let manifest = manifest_with(vec![resolved("C_Sign", 0x10)]);
        let manifest_object = PinnedObjectId(100);

        let plan = build_from_sources_with(
            std::slice::from_ref(&scanned),
            std::slice::from_ref(&manifest),
            &[],
            |_, _| Some(manifest_object),
            |_, _| true,
            None,
            None,
            ExistingAllocation {
                slots: 0,
                active: &BTreeMap::new(),
                revivable: &BTreeMap::new(),
                retired_keys: &BTreeMap::new(),
                retired_slots: &BTreeSet::new(),
                prior_slots: &[],
                prior_identities: &BTreeMap::new(),
                owned: &BTreeMap::new(),
                first_plan: None,
                first_plan_had_provider: false,
            },
            false,
            AdmissionPolicy::detailed(),
            AdmissionScope::Named,
            false,
        );

        assert_eq!(plan.slots.len(), 2, "distinct pinned objects stay distinct");
        let scan_slot = plan
            .slots
            .iter()
            .find(|slot| slot.object == scanned_object)
            .unwrap();
        assert_eq!(scan_slot.semantics, SlotSemantics::COUNT_ONLY);
        assert!(!scan_slot.semantic_authorized);
        // Task 1.3: the unlinked scan slot is unnamed, and an unnamed slot
        // cannot resolve one descriptor.
        assert_eq!(scan_slot.names, ["unknown"]);
        assert!(scan_slot.semantic_ambiguous);
        let manifest_slot = plan
            .slots
            .iter()
            .find(|slot| slot.object == manifest_object)
            .unwrap();
        assert_eq!(
            manifest_slot.semantics,
            crate::kinds::descriptor("C_Sign").unwrap()
        );
        assert!(manifest_slot.semantic_authorized);
    }

