    /// View-collapse fix8 F1: a provisional seed whose retired key
    /// cleared revivable reoccupies its old cell instead of burning a
    /// fresh one per retry. Without clearance, at a wrong position, or
    /// against a mismatched retired slot, the seed fails closed to a
    /// fresh cell.
    #[test]
    fn provisional_seed_revives_a_cleared_retired_cell_in_place() {
        let object = PinnedObjectId(7);
        let mut plan = provisional_plan(object);
        let seed = |file_offset| ProvisionalGetFunctionList {
            module: ModuleId(0),
            object,
            object_path: "/opt/p11.so".into(),
            file_offset,
        };
        let first = plan
            .add_provisional_get_function_list(seed(0x10))
            .unwrap()
            .unwrap();
        assert_eq!(first.index, 0);
        let key = AttachKey::of(&first);
        plan.deactivate(0);
        assert_eq!(plan.slot_index_for_key(key), None);
        // No clearance: a fresh cell, fail closed.
        let fresh = plan
            .add_provisional_get_function_list(seed(0x10))
            .unwrap()
            .unwrap();
        assert_eq!(fresh.index, 1);
        assert_eq!(plan.slots.len(), 2);
        plan.deactivate(1);
        // A clearance for a position with no retired memory fails
        // closed at validation (the retired key sits at 1, not 99).
        plan.set_revivable(BTreeMap::from([(key, RetiredPositions::at(false, 99))]));
        assert!(plan.validate_slot_index().is_err());
        // The cleared, matching cell revives in place: same index, no
        // growth, key re-indexed, retirement cleared, still valid.
        plan.set_revivable(BTreeMap::from([(key, RetiredPositions::at(false, 1))]));
        let revived = plan
            .add_provisional_get_function_list(seed(0x10))
            .unwrap()
            .unwrap();
        assert_eq!(revived.index, 1);
        assert_eq!(plan.slots.len(), 2);
        assert_eq!(plan.slot_index_for_key(key), Some(1));
        assert!(!plan.retired_slots().contains(&1));
        assert!(plan.validate_slot_index().is_ok());
        // Active again: a repeat placement is a no-op.
        assert!(
            plan.add_provisional_get_function_list(seed(0x10))
                .unwrap()
                .is_none()
        );
        // A retired slot that no longer matches fails closed even with
        // a position-matching clearance.
        let other = plan
            .add_provisional_get_function_list(seed(0x20))
            .unwrap()
            .unwrap();
        let other_key = AttachKey::of(&other);
        plan.deactivate(other.index);
        plan.slots[other.index as usize].names = vec!["C_Sign".into()];
        plan.set_revivable(BTreeMap::from([(
            other_key,
            RetiredPositions::at(false, other.index as usize),
        )]));
        let fresh = plan
            .add_provisional_get_function_list(seed(0x20))
            .unwrap()
            .unwrap();
        assert_eq!(fresh.index, 3);
        assert!(plan.validate_slot_index().is_ok());
    }

    /// F6: a provisional seed from a new pin of the same verified file
    /// reoccupies the retired seed cell instead of burning one per pin
    /// generation; a missing identity fails closed to a fresh cell.
    #[test]
    fn provisional_seed_revives_a_same_file_new_pin() {
        let old = PinnedObjectId(7);
        let new = PinnedObjectId(9);
        let seed = |object| ProvisionalGetFunctionList {
            module: ModuleId(0),
            object,
            object_path: "/opt/p11.so".into(),
            file_offset: 0x10,
        };
        let mut plan = provisional_plan(old);
        plan.object_identities
            .insert(old, test_identity(7, "sha-seed"));
        let first = plan
            .add_provisional_get_function_list(seed(old))
            .unwrap()
            .unwrap();
        assert_eq!(first.index, 0);
        plan.deactivate(0);
        plan.revivable.clone_from(&plan.retired_keys);
        plan.modules[0].object = new;
        plan.modules[0].key = ObjectKey {
            device: Device { major: 8, minor: 1 },
            inode: 9,
        };
        // Missing identity on the returning side: fail closed.
        let fresh = plan
            .add_provisional_get_function_list(seed(new))
            .unwrap()
            .unwrap();
        assert_eq!(fresh.index, 1, "no identity, no reclaim");
        plan.deactivate(1);
        plan.forget_retired_key(1);
        plan.revivable.clone_from(&plan.retired_keys);
        plan.object_identities
            .insert(new, test_identity(7, "sha-seed"));
        let revived = plan
            .add_provisional_get_function_list(seed(new))
            .unwrap()
            .unwrap();
        assert_eq!(revived.index, 0, "the same file reoccupies the seed cell");
        assert_eq!(plan.slots.len(), 2);
        assert_eq!(plan.provisional_get_function_list.len(), 1);
        assert!(plan.validate_slot_index().is_ok());
    }

    /// Seed path (tier-3 review of port3 fix2): a new pin's
    /// `C_GetFunctionList` seed forward-flips onto another pin's
    /// retired semantic cell of the same file — the seed-path side of
    /// the cross-pin forward flip. The retired cell carries exactly
    /// `C_GetFunctionList` under the merge-decoded nonzero descriptor
    /// (its semantics still read count-only); the seed reoccupies
    /// index 0 count-only, clears the retirement, and stays
    /// sole-owned and valid. Without the flip the seed burns a fresh
    /// index 1.
    #[test]
    fn provisional_seed_forward_flips_onto_a_retired_semantic_cell() {
        let old = PinnedObjectId(7);
        let new = PinnedObjectId(9);
        let seed = |object| ProvisionalGetFunctionList {
            module: ModuleId(0),
            object,
            object_path: "/opt/p11.so".into(),
            file_offset: 0x10,
        };
        let identity = test_identity(7, "sha-seed-flip");
        let mut plan = provisional_plan(old);
        plan.object_identities.insert(old, identity.clone());
        let first = plan
            .add_provisional_get_function_list(seed(old))
            .unwrap()
            .unwrap();
        assert_eq!(first.index, 0);
        // Promote the seed cell to the shape merge builds for an
        // authorized published `C_GetFunctionList`: the decoded
        // descriptor is nonzero even though its semantics read
        // count-only, so the retirement below is a semantic one.
        let (descriptor, ambiguous) =
            crate::kinds::descriptor_index(&["C_GetFunctionList".to_string()]);
        assert_ne!(descriptor, 0, "the decoded descriptor is semantic-shaped");
        assert!(!ambiguous);
        let slot = &mut plan.slots[0];
        slot.descriptor_index = descriptor;
        slot.semantics = crate::kinds::DESCRIPTORS[descriptor as usize];
        slot.semantic_authorized = true;
        plan.deactivate(0);
        assert_eq!(plan.slot_index_for_key(AttachKey::of(&first)), None);
        plan.revivable.clone_from(&plan.retired_keys);
        plan.modules[0].object = new;
        plan.modules[0].key = ObjectKey {
            device: Device { major: 8, minor: 1 },
            inode: 9,
        };
        plan.object_identities.insert(new, identity);
        let revived = plan
            .add_provisional_get_function_list(seed(new))
            .unwrap()
            .unwrap();
        assert_eq!(
            revived.index, 0,
            "the seed forward-flips onto the retired semantic cell"
        );
        assert_eq!(revived.descriptor_index, 0);
        assert!(!revived.semantic_authorized);
        assert_eq!(revived.names, ["C_GetFunctionList"]);
        assert_eq!(plan.slots.len(), 1, "no fresh cell burns");
        assert_eq!(plan.slot_index_for_key(AttachKey::of(&revived)), Some(0));
        assert!(!plan.retired_slots().contains(&0));
        assert_eq!(plan.module_of_slot(0), Some(ModuleId(0)));
        assert_eq!(plan.module_ambiguous, 0);
        assert_eq!(plan.provisional_get_function_list.len(), 1);
        assert!(plan.validate_slot_index().is_ok());
    }

